	std::string Cipher_Tutorials_Addition_B_ChangeDataType::getStringByLanguage(LanguageType languageType)
	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return "تغيّر هذه الأزرار كيفية عرض الرقم. بدلاً من ذلك، يمكنك الضغط على 1-4 على لوحة المفاتيح لتبديل الأزرار."; }		case LanguageType::BULGARIAN:				{ return "Тези бутони променят начина, по който се показва числото. Алтернативно, можете да натиснете 1-4 на клавиатурата, за да превключвате бутоните."; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "这些按钮可以改变数字的显示方式。或者，您可以按键盘上的1-4来切换按钮。"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "這些按鈕可以改變數字的顯示方式。或者，您可以按鍵盤上的1-4來切換按鈕。"; }
			case LanguageType::CZECH:					{ return "Tato tlačítka mění způsob zobrazení čísla. Alternativně můžete stisknout 1-4 na klávesnici pro přepínání tlačítek."; }		case LanguageType::DANISH:					{ return "Disse knapper ændrer, hvordan tallet vises. Alternativt kan du trykke på 1-4 på tastaturet for at skifte mellem knapperne."; }
			case LanguageType::DUTCH:					{ return "Deze knoppen veranderen de weergave van het getal. Alternatief kunt u op 1-4 op het toetsenbord drukken om de knoppen te wisselen."; }		case LanguageType::FINNISH:					{ return "Nämä painikkeet muuttavat numeron näyttötapaa. Vaihtoehtoisesti voit painaa näppäimistön numeroita 1-4 vaihtaaksesi painikkeiden välillä."; }
			case LanguageType::FRENCH:					{ return "Ces boutons changent la façon dont le nombre est affiché. Alternativement, vous pouvez appuyer sur les touches 1-4 du clavier pour basculer entre les boutons."; }		case LanguageType::GERMAN:					{ return "Diese Tasten ändern die Anzeige der Zahl. Alternativ können Sie 1-4 auf der Tastatur drücken, um die Tasten umzuschalten."; }
			case LanguageType::GREEK:					{ return "Αυτά τα κουμπιά αλλάζουν τον τρόπο εμφάνισης του αριθμού. Εναλλακτικά, μπορείτε να πατήσετε 1-4 στο πληκτρολόγιο για να εναλλάσσετε τα κουμπιά."; }		case LanguageType::HUNGARIAN:				{ return "Ezek a gombok megváltoztatják a szám megjelenítését. Alternatívaként nyomhatja az 1-4 billentyűket a billentyűzeten a gombok váltásához."; }
			case LanguageType::ITALIAN:					{ return "Questi pulsanti cambiano il modo in cui viene visualizzato il numero. In alternativa, puoi premere 1-4 sulla tastiera per alternare i pulsanti."; }		case LanguageType::JAPANESE:				{ return "これらのボタンは、数字の表示方法を変更します。あるいは、キーボードの1-4を押してボタンを切り替えることもできます。"; }
			case LanguageType::KOREAN:					{ return "이 버튼들은 숫자가 표시되는 방식을 변경합니다. 또는 키보드에서 1-4를 눌러 버튼을 전환할 수 있습니다."; }		case LanguageType::NORWEGIAN:				{ return "Disse knappene endrer hvordan tallet vises. Alternativt kan du trykke på 1-4 på tastaturet for å bytte mellom knappene."; }
			case LanguageType::POLISH:					{ return "Te przyciski zmieniają sposób wyświetlania liczby. Alternatywnie można nacisnąć 1-4 na klawiaturze, aby przełączać przyciski."; }		case LanguageType::PORTUGUESE:				{ return "Estes botões mudam a forma como o número é exibido. Alternativamente, você pode pressionar 1-4 no teclado para alternar os botões."; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Estes botões mudam a forma como o número é exibido. Alternativamente, você pode pressionar 1-4 no teclado para alternar os botões."; }		case LanguageType::ROMANIAN:				{ return "Aceste butoane schimbă modul în care este afișat numărul. Alternativ, poți apăsa tastele 1-4 de pe tastatură pentru a comuta butoanele."; }
			case LanguageType::RUSSIAN:					{ return "Эти кнопки изменяют способ отображения числа. Кроме того, вы можете нажать 1-4 на клавиатуре, чтобы переключить кнопки."; }		case LanguageType::SPANISH:					{ return "Estos botones cambian la forma en que se muestra el número. Alternativamente, puedes presionar 1-4 en el teclado para alternar los botones."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "Estos botones cambian la forma en que se muestra el número. Alternativamente, puedes presionar 1-4 en el teclado para alternar los botones."; }	case LanguageType::SWEDISH:					{ return "Dessa knappar ändrar hur siffran visas. Alternativt kan du trycka på 1-4 på tangentbordet för att växla mellan knapparna."; }
			case LanguageType::THAI:					{ return "ปุ่มเหล่านี้เปลี่ยนวิธีการแสดงตัวเลข หรือคุณสามารถกด 1-4 บนแป้นพิมพ์เพื่อสลับปุ่มได้"; }		case LanguageType::TURKISH:					{ return "Bu düğmeler sayının nasıl görüntülendiğini değiştirir. Alternatif olarak, düğmeleri değiştirmek için klavyede 1-4 tuşlarına basabilirsiniz."; }
			case LanguageType::UKRAINIAN:				{ return "Ці кнопки змінюють спосіб відображення числа. Альтернативно, ви можете натиснути 1-4 на клавіатурі, щоб переключити кнопки."; }		case LanguageType::VIETNAMESE:				{ return "Những nút này thay đổi cách hiển thị số. Ngoài ra, bạn có thể nhấn 1-4 trên bàn phím để chuyển đổi các nút."; }
			default: case LanguageType::ENGLISH:		{ return "These buttons change how the number is displayed. Alternatively, you can press 1-4 on the keyboard to toggle the buttons."; }
		}
	}
