	LocalizedString* Hexus_CardDescriptionsLong_Absorb::create() { LocalizedString* instance = new Hexus_CardDescriptionsLong_Absorb(); instance->autorelease(); return instance; }
	LocalizedString* Hexus_CardDescriptionsLong_Absorb::clone() { LocalizedString* clonedString = Hexus_CardDescriptionsLong_Absorb::create(); this->copyAttributesTo(clonedString); return clonedString; }
