	std::string Hexus_CardDescriptionsLong_Absorb::getStringIdentifier() { return "Hexus_CardDescriptionsLong_Absorb"; }
	std::string Hexus_CardDescriptionsLong_Absorb::getStringByLanguage(LanguageType languageType)
	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return "ضع في أي صف. ستقوم هذه البطاقة بصد البطاقة الخاصة التالية التي يلعبها خصمك، إذا كانت تستهدف بطاقة في ذلك الصف."; }		case LanguageType::BULGARIAN:				{ return "Поставете в произволен ред. Тази карта ще блокира следващата специална карта, изиграна от противника ви, ако тя е насочена към карта в този ред."; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "放置到任何一排中。这张卡会阻止对手下一张目标是该排中某张卡的特殊卡。"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "放置到任何一排中。這張卡會阻止對手下一張目標是該排中某張卡的特殊卡。"; }
			case LanguageType::CZECH:					{ return "Umístěte do jakéhokoli řádku. Tato karta zablokuje další speciální kartu hranou vaším soupeřem, pokud cílí na kartu v tomto řádku."; }		case LanguageType::DANISH:					{ return "Placer i en vilkårlig række. Dette kort blokerer for det næste specialkort, din modstander spiller, hvis det er rettet mod et kort i den række."; }
			case LanguageType::DUTCH:					{ return "Plaats in een willekeurige rij. Deze kaart blokkeert de volgende speciale kaart die door je tegenstander wordt gespeeld, als die een kaart in die rij doelwit heeft."; }		case LanguageType::FINNISH:					{ return "Aseta mihin tahansa riviin. Tämä kortti estää seuraavan erikoiskortin, jonka vastustajasi pelaa, jos se kohdistuu korttiin siinä rivissä."; }
			case LanguageType::FRENCH:					{ return "Placez dans n'importe quelle rangée. Cette carte bloquera la prochaine carte spéciale jouée par votre adversaire, si elle cible une carte dans cette rangée."; }		case LanguageType::GERMAN:					{ return "Platzieren Sie diese Karte in eine beliebige Reihe. Diese Karte blockiert die nächste Spezialkarte, die Ihr Gegner spielt, wenn sie auf eine Karte in dieser Reihe abzielt."; }
			case LanguageType::GREEK:					{ return "Τοποθετήστε σε οποιαδήποτε σειρά. Αυτή η κάρτα θα μπλοκάρει την επόμενη ειδική κάρτα που θα παίξει ο αντίπαλός σας, εάν στοχεύει μια κάρτα σε αυτή τη σειρά."; }		case LanguageType::HUNGARIAN:				{ return "Helyezd el bármely sorba. Ez a kártya blokkolja a következő speciális kártyát, amelyet az ellenfeled játszik, ha az egy kártyát céloz meg abban a sorban."; }
			case LanguageType::ITALIAN:					{ return "Metti in qualsiasi fila. Questa carta bloccherà la prossima carta speciale giocata dal tuo avversario, se prende di mira una carta in quella fila."; }		case LanguageType::JAPANESE:				{ return "任意の列に配置してください。このカードは、対戦相手が次に使用する特殊カードをブロックします（その列にあるカードを対象とする場合）。"; }
			case LanguageType::KOREAN:					{ return "어느 줄에나 놓으십시오. 이 카드는 상대방이 다음에 사용할 특별 카드를 차단합니다. 해당 줄에 있는 카드를 대상으로 하는 경우에만 차단합니다."; }		case LanguageType::NORWEGIAN:				{ return "Plasser i en hvilken som helst rad. Dette kortet vil blokkere det neste spesialkortet som spilles av motstanderen din, hvis det retter seg mot et kort i den raden."; }
			case LanguageType::POLISH:					{ return "Umieść w dowolnym rzędzie. Ta karta zablokuje następną specjalną kartę zagraną przez przeciwnika, jeśli celuje ona w kartę w tym rzędzie."; }		case LanguageType::PORTUGUESE:				{ return "Coloque em qualquer fileira. Este cartão bloqueará o próximo cartão especial jogado pelo seu oponente, se ele mirar em um cartão nessa fileira."; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Coloque em qualquer fileira. Este cartão bloqueará a próxima carta especial jogada pelo seu oponente, se ela mirar em uma carta nessa fileira."; }		case LanguageType::ROMANIAN:				{ return "Plasați în orice rând. Această carte va bloca următoarea carte specială jucată de adversar, dacă vizează o carte în acel rând."; }
			case LanguageType::RUSSIAN:					{ return "Поместите в любой ряд. Эта карта заблокирует следующую специальную карту, сыгранную вашим противником, если она нацелена на карту в этом ряду."; }		case LanguageType::SPANISH:					{ return "Coloca en cualquier fila. Esta carta bloqueará la próxima carta especial jugada por tu oponente, si apunta a una carta en esa fila."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "Coloca en cualquier fila. Esta carta bloqueará la próxima carta especial jugada por tu oponente, si apunta a una carta en esa fila."; }	case LanguageType::SWEDISH:					{ return "Placera i valfri rad. Detta kort kommer att blockera nästa specialkort som spelas av din motståndare, om det riktar sig mot ett kort i den raden."; }
			case LanguageType::THAI:					{ return "วางในแถวใดก็ได้ การ์ดนี้จะบล็อกการ์ดพิเศษใบถัดไปที่เล่นโดยคู่ต่อสู้ของคุณ หากมันเล็งไปที่การ์ดในแถวนั้น"; }		case LanguageType::TURKISH:					{ return "Herhangi bir sıraya yerleştirin. Bu kart, rakibinizin oynadığı bir sonraki özel kartı, o sıradaki bir kartı hedefliyorsa engelleyecektir."; }
			case LanguageType::UKRAINIAN:				{ return "Розмістіть у будь-якому рядку. Ця картка заблокує наступну спеціальну картку, зіграну вашим суперником, якщо вона націлена на картку в цьому рядку."; }		case LanguageType::VIETNAMESE:				{ return "Đặt vào bất kỳ hàng nào. Thẻ này sẽ chặn thẻ đặc biệt tiếp theo được chơi bởi đối thủ của bạn, nếu nó nhắm mục tiêu vào một thẻ trong hàng đó."; }
			default: case LanguageType::ENGLISH:		{ return "Place into any row. This card will block the next special card played by your opponent, if it targets a card in that row."; }
		}
	}
