	std::string Hexus_CardDescriptionsLong_Addition::getStringIdentifier() { return "Hexus_CardDescriptionsLong_Addition"; }
	std::string Hexus_CardDescriptionsLong_Addition::getStringByLanguage(LanguageType languageType)
	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return "حدد إحدى بطاقاتك وأضف قيمتها إلى بطاقة أخرى. يتم تخزين النتيجة في البطاقة المستهدفة. القيم الأكبر من أو تساوي 16 ستسبب في تجاوز السعة."; }		case LanguageType::BULGARIAN:				{ return "Изберете една от вашите карти и добавете стойността ѝ към друга карта. Резултатът се записва в целевата карта. Стойности, по-големи или равни на 16, ще доведат до преливане."; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "选择你的其中一张卡片，并将其数值加到另一张卡片上。结果存储在目标卡片中。数值大于或等于16将导致溢出。"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "選擇你的其中一張卡片，並將其數值加到另一張卡片上。結果存儲在目標卡片中。數值大於或等於16將導致溢出。"; }
			case LanguageType::CZECH:					{ return "Vyberte jednu ze svých karet a přidejte její hodnotu k jiné kartě. Výsledek je uložen do cílové karty. Hodnoty větší nebo rovné 16 způsobí přetečení."; }		case LanguageType::DANISH:					{ return "Vælg et af dine kort og tilføj dets værdi til et andet kort. Resultatet gemmes i målrettet kort. Værdier større end eller lig med 16 vil resultere i overflow."; }
			case LanguageType::DUTCH:					{ return "Selecteer een van je kaarten en voeg de waarde toe aan een andere kaart. Het resultaat wordt opgeslagen in de doelkaart. Waarden groter dan of gelijk aan 16 resulteren in een overflow."; }		case LanguageType::FINNISH:					{ return "Valitse yksi korteistasi ja lisää sen arvo toiseen korttiin. Tulos tallennetaan kohdekorttiin. Arvot, jotka ovat suurempia tai yhtä suuria kuin 16, aiheuttavat ylivuodon."; }
			case LanguageType::FRENCH:					{ return "Sélectionnez une de vos cartes et ajoutez sa valeur à une autre carte. Le résultat est stocké dans la carte cible. Les valeurs supérieures ou égales à 16 entraîneront un dépassement."; }		case LanguageType::GERMAN:					{ return "Wählen Sie eine Ihrer Karten aus und addieren Sie deren Wert zu einer anderen Karte. Das Ergebnis wird in der Zielkarte gespeichert. Werte größer oder gleich 16 führen zu einem Überlauf."; }
			case LanguageType::GREEK:					{ return "Επιλέξτε μία από τις κάρτες σας και προσθέστε την τιμή της σε μια άλλη κάρτα. Το αποτέλεσμα αποθηκεύεται στην κάρτα στόχο. Τιμές μεγαλύτερες ή ίσες με 16 θα οδηγήσουν σε υπερχείλιση."; }		case LanguageType::HUNGARIAN:				{ return "Válassz egyet a kártyáid közül, és add hozzá annak értékét egy másik kártyához. Az eredmény a célkártyában kerül tárolásra. A 16-nál nagyobb vagy egyenlő értékek túlcsordulást eredményeznek."; }
			case LanguageType::ITALIAN:					{ return "Seleziona una delle tue carte e aggiungi il suo valore a un'altra carta. Il risultato viene memorizzato nella carta bersaglio. I valori maggiori o uguali a 16 risulteranno in un overflow."; }		case LanguageType::JAPANESE:				{ return "自分のカードのうち1枚を選択し、その値を別のカードに加えます。結果はターゲットカードに格納されます。16以上の値はオーバーフローを引き起こします。"; }
			case LanguageType::KOREAN:					{ return "당신의 카드 중 하나를 선택하고 그 값을 다른 카드에 더하십시오. 결과는 대상 카드에 저장됩니다. 16 이상 값은 오버플로우를 초래합니다."; }		case LanguageType::NORWEGIAN:				{ return "Velg ett av kortene dine og legg til verdien på et annet kort. Resultatet lagres i målrettet kort. Verdier større enn eller lik 16 vil resultere i overflow."; }
			case LanguageType::POLISH:					{ return "Wybierz jedną ze swoich kart i dodaj jej wartość do innej karty. Wynik jest przechowywany w karcie docelowej. Wartości większe lub równe 16 spowodują przepełnienie."; }		case LanguageType::PORTUGUESE:				{ return "Selecione uma das suas cartas e adicione o seu valor a outra carta. O resultado é armazenado na carta alvo. Valores maiores ou iguais a 16 resultarão em um overflow."; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Selecione uma das suas cartas e adicione o seu valor a outra carta. O resultado é armazenado na carta alvo. Valores maiores ou iguais a 16 resultarão em um overflow."; }		case LanguageType::ROMANIAN:				{ return "Selectați una dintre cărțile dvs. și adăugați valoarea acesteia la o altă carte. Rezultatul este stocat în cartea țintă. Valorile mai mari sau egale cu 16 vor rezulta într-un overflow."; }
			case LanguageType::RUSSIAN:					{ return "Выберите одну из ваших карт и добавьте её значение к другой карте. Результат сохранится в целевой карте. Значения больше или равные 16 приведут к переполнению."; }		case LanguageType::SPANISH:					{ return "Selecciona una de tus cartas y añade su valor a otra carta. El resultado se almacena en la carta objetivo. Los valores mayores o iguales a 16 resultarán en un desbordamiento."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "Selecciona una de tus cartas y añade su valor a otra carta. El resultado se almacena en la carta objetivo. Los valores mayores o iguales a 16 resultarán en un desbordamiento."; }	case LanguageType::SWEDISH:					{ return "Välj ett av dina kort och lägg dess värde till ett annat kort. Resultatet lagras i mål kortet. Värden större än eller lika med 16 kommer att resultera i overflow."; }
			case LanguageType::THAI:					{ return "เลือกการ์ดหนึ่งใบของคุณและเพิ่มมูลค่าของมันลงในอีกการ์ดหนึ่ง ผลลัพธ์จะถูกเก็บไว้ในการ์ดเป้าหมาย ค่าที่มากกว่าหรือเท่ากับ 16 จะส่งผลให้เกิดโอเวอร์โฟลว์"; }		case LanguageType::TURKISH:					{ return "Kartlarınızdan birini seçin ve değerini başka bir karta ekleyin. Sonuç, hedef kartta saklanır. 16 veya daha büyük değerler taşmaya neden olacaktır."; }
			case LanguageType::UKRAINIAN:				{ return "Виберіть одну зі своїх карт і додайте її значення до іншої карти. Результат зберігається в цільовій карті. Значення, більші або рівні 16, призведуть до переповнення."; }		case LanguageType::VIETNAMESE:				{ return "Chọn một trong những thẻ của bạn và cộng giá trị của nó vào một thẻ khác. Kết quả được lưu trữ trong thẻ mục tiêu. Các giá trị lớn hơn hoặc bằng 16 sẽ gây tràn số."; }
			default: case LanguageType::ENGLISH:		{ return "Select one of your cards and add its value to another card. The result is stored in the target card. Values greater than or equal to 16 will result in an overflow."; }
		}
	}
