	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return "عند لعب هذه البطاقة، ستلعب جميع النسخ من هذه البطاقة من يدك و مجموعتك."; }		case LanguageType::BULGARIAN:				{ return "Когато тази карта бъде изиграна, всички копия на тази карта ще бъдат изиграни от ръката и тестето ви."; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "当这张卡被打出时，你手牌和牌库中的所有该卡牌的复制品都会被打出。"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "當這張卡片被打出時，你手牌和牌庫中的所有該卡片的複製品都會被打出。"; }
			case LanguageType::CZECH:					{ return "Když je tato karta zahrána, všechny kopie této karty budou zahrány z vaší ruky a balíčku."; }		case LanguageType::DANISH:					{ return "Når dette kort spilles, vil alle kopier af dette kort blive spillet fra din hånd og dæk."; }
			case LanguageType::DUTCH:					{ return "Wanneer deze kaart wordt gespeeld, worden alle kopieën van deze kaart uit je hand en deck gespeeld."; }		case LanguageType::FINNISH:					{ return "Kun tämä kortti pelataan, kaikki tämän kortin kopiot pelataan kädestäsi ja pakastasi."; }
			case LanguageType::FRENCH:					{ return "Lorsque cette carte est jouée, toutes les copies de cette carte seront jouées depuis votre main et votre deck."; }		case LanguageType::GERMAN:					{ return "Wenn diese Karte gespielt wird, werden alle Kopien dieser Karte aus deiner Hand und deinem Deck gespielt."; }
			case LanguageType::GREEK:					{ return "Όταν παιχτεί αυτή η κάρτα, όλες οι αντίγραφες αυτής της κάρτας θα παιχτούν από το χέρι και την τράπουλά σας."; }		case LanguageType::HUNGARIAN:				{ return "Amikor ezt a kártyát kijátsszák, a kezedből és a paklidból minden másolatát kijátsszák."; }
			case LanguageType::ITALIAN:					{ return "Quando questa carta viene giocata, tutte le copie di questa carta saranno giocate dalla tua mano e dal tuo mazzo."; }		case LanguageType::JAPANESE:				{ return "このカードがプレイされたとき、このカードのすべてのコピーがあなたの手札とデッキからプレイされます。"; }
			case LanguageType::KOREAN:					{ return "이 카드를 플레이하면, 이 카드의 모든 복사본이 손과 덱에서 플레이됩니다."; }		case LanguageType::NORWEGIAN:				{ return "Når dette kortet spilles, vil alle kopier av dette kortet spilles fra hånden og kortstokken din."; }
			case LanguageType::POLISH:					{ return "Kiedy ta karta zostanie zagrana, wszystkie kopie tej karty zostaną zagrane z twojej ręki i talii."; }		case LanguageType::PORTUGUESE:				{ return "Quando este cartão for jogado, todas as cópias deste cartão serão jogadas da sua mão e do seu baralho."; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Quando esta carta for jogada, todas as cópias desta carta serão jogadas da sua mão e do seu baralho."; }		case LanguageType::ROMANIAN:				{ return "Când această carte este jucată, toate copiile acestei cărți vor fi jucate din mâna și pachetul tău."; }
			case LanguageType::RUSSIAN:					{ return "Когда эта карта сыграна, все копии этой карты будут сыграны из вашей руки и колоды."; }		case LanguageType::SPANISH:					{ return "Cuando esta carta se juegue, todas las copias de esta carta se jugarán de tu mano y mazo."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "Cuando esta carta se juegue, todas las copias de esta carta se jugarán de tu mano y mazo."; }	case LanguageType::SWEDISH:					{ return "När detta kort spelas, kommer alla kopior av detta kort att spelas från din hand och lek."; }
			case LanguageType::THAI:					{ return "เมื่อการ์ดใบนี้ถูกเล่น การ์ดใบนี้ทั้งหมดที่เหลือจะถูกเล่นจากมือและเด็คของคุณ"; }		case LanguageType::TURKISH:					{ return "Bu kart oynandığında, elinizden ve destenizden bu kartın tüm kopyaları oynanacaktır."; }
			case LanguageType::UKRAINIAN:				{ return "Коли ця картка зіграна, усі копії цієї картки будуть зіграні з вашої руки та колоди."; }		case LanguageType::VIETNAMESE:				{ return "Khi lá bài này được chơi, tất cả các bản sao của lá bài này sẽ được chơi từ tay và bộ bài của bạn."; }
			default: case LanguageType::ENGLISH:		{ return "When this card is played, all copies of this card will be played from your hand and deck."; }
		}
	}
