	LocalizedString* Hexus_CardDescriptionsLong_LogicalAnd::create() { LocalizedString* instance = new Hexus_CardDescriptionsLong_LogicalAnd(); instance->autorelease(); return instance; }
	LocalizedString* Hexus_CardDescriptionsLong_LogicalAnd::clone() { LocalizedString* clonedString = Hexus_CardDescriptionsLong_LogicalAnd::create(); this->copyAttributesTo(clonedString); return clonedString; }
