	std::string Hexus_Tutorials_A_LossDisplay::getStringByLanguage(LanguageType languageType)
	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return "يبدأ كل لاعب اللعبة مع حياتين. اللاعب صاحب أقل نقاط في نهاية الجولة سيخسر حياة. في هذه اللعبة، كلا اللاعبين خسرا حياة واحدة."; }		case LanguageType::BULGARIAN:				{ return "Всеки играч започва играта с 2 живота. Играчът с най-нисък резултат в края на рунда губи живот. В тази игра и двамата играчи са загубили по 1 живот."; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "每个玩家游戏开始时有2条命。 一轮结束时得分最低的玩家将失去一条命。 在这个游戏中，双方玩家都失去了一条命。"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "每個玩家遊戲開始時有 2 條命。 一輪結束時得分最低的玩家將失去一條命。 在這個遊戲中，雙方玩家都失去了一條命。"; }
			case LanguageType::CZECH:					{ return "Každý hráč začíná hru se 2 životy. Hráč s nejnižším skóre na konci kola ztrácí život. V této hře oba hráči ztratili 1 život."; }		case LanguageType::DANISH:					{ return "Hver spiller starter spillet med 2 liv. Spilleren med den laveste score i slutningen af en runde mister et liv. I dette spil har begge spillere mistet 1 liv."; }
			case LanguageType::DUTCH:					{ return "Elke speler begint het spel met 2 levens. De speler met de laagste score aan het einde van een ronde verliest een leven. In dit spel hebben beide spelers 1 leven verloren."; }		case LanguageType::FINNISH:					{ return "Jokaisella pelaajalla on pelin alussa 2 elämää. Kierroksen lopussa pelaaja, jolla on alin pistemäärä, menettää yhden elämän. Tässä pelissä molemmat pelaajat ovat menettäneet 1 elämän."; }
			case LanguageType::FRENCH:					{ return "Chaque joueur commence la partie avec 2 vies. Le joueur avec le score le plus bas à la fin d'un tour perd une vie. Dans cette partie, les deux joueurs ont perdu 1 vie."; }		case LanguageType::GERMAN:					{ return "Jeder Spieler beginnt das Spiel mit 2 Leben. Der Spieler mit der niedrigsten Punktzahl am Ende einer Runde verliert ein Leben. In diesem Spiel haben beide Spieler 1 Leben verloren."; }
			case LanguageType::GREEK:					{ return "Κάθε παίκτης ξεκινάει το παιχνίδι με 2 ζωές. Ο παίκτης με τη χαμηλότερη βαθμολογία στο τέλος ενός γύρου θα χάσει μία ζωή. Σε αυτό το παιχνίδι, και οι δύο παίκτες έχουν χάσει 1 ζωή."; }		case LanguageType::HUNGARIAN:				{ return "Minden játékos 2 élettel kezdi a játékot. A kör végén a legalacsonyabb pontszámú játékos elveszít egy életet. Ebben a játékban mindkét játékos elveszített 1 életet."; }
			case LanguageType::ITALIAN:					{ return "Ogni giocatore inizia la partita con 2 vite. Il giocatore con il punteggio più basso alla fine di un turno perde una vita. In questo gioco, entrambi i giocatori hanno perso 1 vita."; }		case LanguageType::JAPANESE:				{ return "各プレイヤーは2つのライフでゲームを開始します。ラウンド終了時に最もスコアが低いプレイヤーがライフを1つ失います。このゲームでは、両方のプレイヤーが1つのライフを失いました。"; }
			case LanguageType::KOREAN:					{ return "각 플레이어는 2개의 생명으로 게임을 시작합니다. 라운드가 끝날 때 점수가 가장 낮은 플레이어는 생명을 잃게 됩니다. 이 게임에서는 두 플레이어 모두 생명 1개를 잃었습니다."; }		case LanguageType::NORWEGIAN:				{ return "Hver spiller starter spillet med 2 liv. Spilleren med lavest poengsum ved slutten av en runde mister et liv. I dette spillet har begge spillere mistet 1 liv."; }
			case LanguageType::POLISH:					{ return "Każdy gracz zaczyna grę z 2 życiami. Gracz z najniższym wynikiem na koniec rundy traci jedno życie. W tej grze obaj gracze stracili po 1 życiu."; }		case LanguageType::PORTUGUESE:				{ return "Cada jogador começa o jogo com 2 vidas. O jogador com a menor pontuação no final de uma rodada perderá uma vida. Neste jogo, ambos os jogadores perderam 1 vida."; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Cada jogador começa o jogo com 2 vidas. O jogador com a menor pontuação no final de uma rodada perderá uma vida. Neste jogo, ambos os jogadores perderam 1 vida."; }		case LanguageType::ROMANIAN:				{ return "Fiecare jucător începe jocul cu 2 vieți. Jucătorul cu cel mai mic scor la sfârșitul unei runde va pierde o viață. În acest joc, ambii jucători au pierdut 1 viață."; }
			case LanguageType::RUSSIAN:					{ return "Каждый игрок начинает игру с 2 жизнями. Игрок с наименьшим количеством очков в конце раунда теряет жизнь. В этой игре оба игрока потеряли по 1 жизни."; }		case LanguageType::SPANISH:					{ return "Cada jugador comienza el juego con 2 vidas. El jugador con la puntuación más baja al final de una ronda perderá una vida. En este juego, ambos jugadores han perdido 1 vida."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "Cada jugador comienza el juego con 2 vidas. El jugador con la puntuación más baja al final de una ronda perderá una vida. En este juego, ambos jugadores han perdido 1 vida."; }	case LanguageType::SWEDISH:					{ return "Varje spelare börjar spelet med 2 liv. Spelaren med den lägsta poängen i slutet av en omgång förlorar ett liv. I det här spelet har båda spelarna förlorat 1 liv."; }
			case LanguageType::THAI:					{ return "ผู้เล่นแต่ละคนเริ่มเกมด้วยชีวิต 2 ครั้ง ผู้เล่นที่มีคะแนนต่ำสุดเมื่อจบแต่ละรอบจะเสียชีวิต 1 ครั้ง ในเกมนี้ ผู้เล่นทั้งคู่เสียชีวิตไปแล้ว 1 ครั้ง"; }		case LanguageType::TURKISH:					{ return "Her oyuncu oyuna 2 can ile başlar. Bir tur sonunda en düşük skora sahip oyuncu bir can kaybeder. Bu oyunda her iki oyuncu da 1 can kaybetmiştir."; }
			case LanguageType::UKRAINIAN:				{ return "Кожен гравець починає гру з 2 життями. Гравець з найнижчим рахунком в кінці раунду втратить одне життя. У цій грі обидва гравці втратили по 1 життю."; }		case LanguageType::VIETNAMESE:				{ return "Mỗi người chơi bắt đầu trò chơi với 2 mạng. Người chơi có điểm số thấp nhất vào cuối vòng sẽ mất một mạng. Trong trò chơi này, cả hai người chơi đều đã mất 1 mạng."; }
			default: case LanguageType::ENGLISH:		{ return "Each player starts the game with 2 lives. The player with the lowest score at the end of a round will lose a life. In this game, both players have lost 1 life."; }
		}
	}
