			case LanguageType::ITALIAN:					{ return "'call' è simile a 'jmp', tranne per il fatto che spinge un indirizzo nello stack. La prossima istruzione 'ret' tornerà all'istruzione successiva dopo il 'call'."; }		case LanguageType::JAPANESE:				{ return "'call' は 'jmp' に似ていますが、アドレスをスタックにプッシュします。次の 'ret' 命令は 'call' の後の次の命令に戻ります。"; }
			case LanguageType::KOREAN:					{ return "'call'은 'jmp'와 유사하지만 주소를 스택에 푸시합니다. 다음 'ret' 명령은 'call' 다음 명령으로 돌아갑니다."; }		case LanguageType::NORWEGIAN:				{ return "'call' ligner på 'jmp', bortsett fra at den skyver en adresse til stakken. Den neste 'ret'-instruksjonen vil gå tilbake til instruksjonen etter 'call'."; }
			case LanguageType::POLISH:					{ return "'call' jest podobna do 'jmp', z wyjątkiem tego, że wpycha adres na stos. Następna instrukcja 'ret' wróci do następnej instrukcji po 'call'."; }		case LanguageType::PORTUGUESE:				{ return "'call' é semelhante a 'jmp', exceto que coloca um endereço na pilha. A próxima instrução 'ret' retornará à próxima instrução após o 'call'."; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "'call' é semelhante a 'jmp', exceto que coloca um endereço na pilha. A próxima instrução 'ret' retornará à próxima instrução após o 'call'."; }		case LanguageType::ROMANIAN:				{ return "'call' este similar cu 'jmp', cu excepția faptului că împinge o adresă pe stivă. Următoarea instrucțiune 'ret' va reveni la următoarea instrucțiune după 'call'."; }
			case LanguageType::RUSSIAN:					{ return "'call' аналогична 'jmp', за исключением того, что она помещает адрес в стек. Следующая инструкция 'ret' вернется к следующей инструкции после 'call'."; }		case LanguageType::SPANISH:					{ return "'call' es similar a 'jmp', excepto que empuja una dirección a la pila. La siguiente instrucción 'ret' volverá a la siguiente instrucción después del 'call'."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "'call' es similar a 'jmp', excepto que empuja una dirección a la pila. La siguiente instrucción 'ret' volverá a la siguiente instrucción después del 'call'."; }	case LanguageType::SWEDISH:					{ return "'call' liknar 'jmp', förutom att den skjuter en adress till stacken. Nästa 'ret'-instruktion kommer att återgå till nästa instruktion efter 'call'."; }
