			case LanguageType::RUSSIAN:					{ return "JP/JNP/JPE/JPO — это инструкции, которые выполняют скачок только в зависимости от того, имеет ли результат последней арифметической инструкции четное или нечетное число битов."; }		case LanguageType::SPANISH:					{ return "JP/JNP/JPE/JPO son instrucciones que sólo realizan un salto dependiendo de si el resultado de la instrucción aritmética más reciente tiene un número par o impar de bits."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "JP/JNP/JPE/JPO son instrucciones que sólo realizan un salto dependiendo de si el resultado de la instrucción aritmética más reciente tiene un número par o impar de bits."; }	case LanguageType::SWEDISH:					{ return "JP/JNP/JPE/JPO är instruktioner som bara utför ett hopp beroende på om resultatet av den senaste aritmetiska instruktionen har ett udda eller jämnt antal bitar."; }
			case LanguageType::THAI:					{ return "JP/JNP/JPE/JPO เป็นคําแนะนําที่ทําการกระโดดเท่านั้นขึ้นอยู่กับว่าผลลัพธ์ของคําสั่งเลขคณิตล่าสุดมีจํานวนบิตคี่หรือคู่"; }		case LanguageType::TURKISH:					{ return "JP / JNP / JPE / JPO, en son aritmetik talimatın sonucunun tek veya çift sayıda bit içermesine bağlı olarak yalnızca bir sıçrama gerçekleştiren talimatlardır."; }
			case LanguageType::UKRAINIAN:				{ return "JP/JNP/JPE/JPO — це інструкції, які виконують лише перехід залежно від того, чи результат останньої арифметичної інструкції має непарну або парну кількість бітів."; }		case LanguageType::VIETNAMESE:				{ return "JP / JNP / JPE / JPO là các hướng dẫn chỉ thực hiện một bước nhảy tùy thuộc vào việc kết quả của hướng dẫn số học gần đây nhất có số bit lẻ hay chẵn."; }
			default: case LanguageType::ENGLISH:		{ return "JP/JNP/JPE/JPO are instructions that only perform a jump depending on whether the result of the most recent arithmetic instruction has an odd or even number of bits."; }
