	std::string Menus_Hacking_Lexicon_Pages_Data_OffsetHelp12::getStringByLanguage(LanguageType languageType)
	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return ".لماذا هذا +12 بدلا من +3؟ وذلك لأن الأرقام التي يتم تعقبها هي أعداد صحيحة ، والتي تستهلك 4 بايتات من الذاكرة لكل منها ، وبالتالي فإن ثلاثة من هذه الأرقام تجعل 12 بايت في المجموع"; }		case LanguageType::BULGARIAN:				{ return "Защо това +12 вместо +3? Това е така, защото проследените числа са цели числа, които заемат по 4 байта всяка памет, така че три от тях са общо 12 байта."; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "为什么这个+12而不是+3？这是因为被跟踪的数字是整数，每个占用4个字节的内存，因此其中三个共计12个字节。"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "為什麼這個+12而不是+3？這是因為被跟踪的數字是整數，每個佔用4個字節的內存，因此其中三個共計12個字節。"; }
			case LanguageType::CZECH:					{ return "Proč je tento +12 namísto +3? Důvodem je, že sledovaná čísla jsou celá čísla, která zabírají 4 bajty paměti, takže celkem tři z nich tvoří celkem 12 bajtů."; }		case LanguageType::DANISH:					{ return "Hvorfor er dette +12 i stedet for +3? Dette skyldes, at de tal, der spores, er heltal, der optager 4 bytes hukommelse hver, så tre af disse giver 12 bytes i alt."; }
			case LanguageType::DUTCH:					{ return "Waarom is deze +12 in plaats van +3? Dit komt omdat de nummers die worden bijgehouden, gehele getallen zijn, die elk 4 bytes aan geheugen innemen, dus drie hiervan maken in totaal 12 bytes."; }		case LanguageType::FINNISH:					{ return "Miksi tämä +12 on +3: n sijaan? Tämä johtuu siitä, että seurattavat numerot ovat kokonaislukuja, jotka vievät 4 tavua muistia, joten kolme näistä muodostaa yhteensä 12 tavua."; }
			case LanguageType::FRENCH:					{ return "Pourquoi est-ce +12 au lieu de +3? Cela est dû au fait que les nombres suivis sont des entiers, qui occupent chacun 4 octets de mémoire. Trois de ces enregistrements totalisent donc 12 octets."; }		case LanguageType::GERMAN:					{ return "Warum ist das +12 statt +3? Dies liegt daran, dass die verfolgten Zahlen Ganzzahlen sind, die jeweils 4 Byte Speicher belegen, sodass drei davon insgesamt 12 Byte ergeben."; }
			case LanguageType::GREEK:					{ return "Γιατί είναι αυτό το +12 αντί του +3; Αυτό συμβαίνει επειδή οι αριθμοί που παρακολουθούνται είναι ακέραιοι αριθμοί, οι οποίοι καταλαμβάνουν 4 byte μνήμης το καθένα, έτσι ώστε τρεις από αυτές να κάνουν 12 bytes συνολικά."; }		case LanguageType::HUNGARIAN:				{ return "Miért van ez az +12 a +3 helyett? Ez azért van, mert a nyomon követhető számok egész számok, amelyek mindegyike 4 bájtnyi memóriát foglal magába, így ezek közül három összesen 12 bájtot tesz ki."; }
			case LanguageType::ITALIAN:					{ return "Perché questa +12 invece di +3? Questo perché i numeri che vengono tracciati sono numeri interi, che occupano ciascuno 4 byte di memoria ciascuno, quindi tre di questi rendono 12 byte in totale."; }		case LanguageType::JAPANESE:				{ return "これはなぜ+3の代わりに+12なのですか？これは、追跡されている数字が整数で、それぞれ4バイトのメモリを占有するため、そのうち3つが合計12バイトになるためです。"; }
			case LanguageType::KOREAN:					{ return "+3가 아닌 왜 +12입니까? 이는 추적되는 숫자가 각각 4 바이트의 메모리를 차지하는 정수이기 때문에 이들 중 3 개가 총 12 바이트를 차지하기 때문입니다."; }		case LanguageType::NORWEGIAN:				{ return "Hvorfor er dette +12 i stedet for +3? Dette skyldes at tallene som spores er heltall, som tar opp 4 bytes minne hver, slik at tre av disse gir 12 byte totalt."; }
			case LanguageType::POLISH:					{ return "Dlaczego ten +12 zamiast +3? Dzieje się tak, ponieważ śledzone liczby są liczbami całkowitymi, które zajmują po 4 bajty pamięci, więc trzy z nich tworzą łącznie 12 bajtów."; }		case LanguageType::PORTUGUESE:				{ return "Por que isso é +12 em vez de +3? Isso ocorre porque os números que estão sendo rastreados são números inteiros, que ocupam 4 bytes de memória cada, portanto, três deles formam 12 bytes no total."; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Por que isso é +12 em vez de +3? Isso ocorre porque os números que estão sendo rastreados são números inteiros, que ocupam 4 bytes de memória cada, portanto, três deles formam 12 bytes no total."; }		case LanguageType::ROMANIAN:				{ return "De ce este acest +12 în loc de +3? Acest lucru se datorează faptului că numerele care sunt urmărite sunt numere întregi, care ocupă câte 4 octeți de memorie fiecare, astfel că trei dintre acestea produc 12 octeți în total."; }
			case LanguageType::RUSSIAN:					{ return "Почему этот +12 вместо +3? Это связано с тем, что отслеживаемые числа являются целыми числами, каждый из которых занимает 4 байта памяти, поэтому три из них составляют в общей сложности 12 байтов."; }		case LanguageType::SPANISH:					{ return "¿Por qué es este +12 en lugar de +3? Esto se debe a que los números que se rastrean son enteros, que ocupan 4 bytes de memoria cada uno, por lo que tres de ellos forman 12 bytes en total."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "¿Por qué es este +12 en lugar de +3? Esto se debe a que los números que se rastrean son enteros, que ocupan 4 bytes de memoria cada uno, por lo que tres de ellos forman 12 bytes en total."; }	case LanguageType::SWEDISH:					{ return "Varför är det här +12 istället för +3? Detta beror på att numren som spåras är heltal, som tar upp 4 byte minne varje, så tre av dessa gör 12 byte totalt."; }
			case LanguageType::THAI:					{ return "ทำไม +12 นี้แทน +3 นี่เป็นเพราะตัวเลขที่ถูกติดตามนั้นเป็นจำนวนเต็มซึ่งใช้หน่วยความจำ 4 ไบต์ต่อกันดังนั้นสามในจำนวนนี้จึงรวม 12 ไบต์"; }		case LanguageType::TURKISH:					{ return "Neden +3 yerine bu +12? Bunun nedeni, izlenen sayıların her biri 4 byte hafıza alan tamsayılar olması, bunlardan üçünün toplamda 12 byte olması."; }
			case LanguageType::UKRAINIAN:				{ return "Чому цей +12 замість +3? Це пояснюється тим, що відстежувані числа - це цілі числа, які займають по 4 байта пам'яті, так що три з них складають загалом 12 байт."; }		case LanguageType::VIETNAMESE:				{ return "Tại sao +12 này thay vì +3? Điều này là do các số được theo dõi là các số nguyên, chiếm 4 byte bộ nhớ mỗi số, vì vậy ba trong số này tạo ra tổng cộng 12 byte."; }
			default: case LanguageType::ENGLISH:		{ return "Why is this +12 instead of +3? This is because the numbers being tracked are integers, which take up 4 bytes of memory each, so three of these makes 12 bytes in total."; }
		}
	}
