	std::string Menus_Hacking_Lexicon_Pages_Data_OffsetHelp4::getStringByLanguage(LanguageType languageType)
	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return ".لماذا هذا +4 بدلا من +1؟ وذلك لأن الأرقام التي يتم تعقبها هي أعداد صحيحة ، والتي تستهلك 4 بايت من الذاكرة"; }		case LanguageType::BULGARIAN:				{ return "Защо това +4 вместо +1? Това е така, защото проследените числа са цели числа, които заемат 4 байта памет."; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "为什么这个+4而不是+1？这是因为被跟踪的数字是整数，占用4个字节的内存。"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "為什麼這個+4而不是+1？這是因為被跟踪的數字是整數，佔用4個字節的內存。"; }
			case LanguageType::CZECH:					{ return "Proč je tento +4 namísto +1? Důvodem je, že sledovaná čísla jsou celá čísla, která zabírají 4 bajty paměti."; }		case LanguageType::DANISH:					{ return "Hvorfor er dette +4 i stedet for +1? Dette skyldes, at de tal, der spores, er heltal, der optager 4 bytes hukommelse."; }
			case LanguageType::DUTCH:					{ return "Waarom is deze +4 in plaats van +1? Dit komt omdat de getallen die worden bijgehouden, gehele getallen zijn, die 4 bytes aan geheugen innemen."; }		case LanguageType::FINNISH:					{ return "Miksi tämä +4 on +1: n sijaan? Tämä johtuu siitä, että seurattavat numerot ovat kokonaislukuja, jotka vievät 4 tavua muistia."; }
			case LanguageType::FRENCH:					{ return "Pourquoi est-ce +4 au lieu de +1? En effet, les numéros suivis sont des entiers, qui occupent 4 octets de mémoire."; }		case LanguageType::GERMAN:					{ return "Warum ist das +4 statt +1? Dies liegt daran, dass die verfolgten Zahlen Ganzzahlen sind, die 4 Byte Speicher belegen."; }
			case LanguageType::GREEK:					{ return "Γιατί είναι αυτό το +4 αντί του +1; Αυτό οφείλεται στο γεγονός ότι οι αριθμοί που παρακολουθούνται είναι ακέραιοι, οι οποίοι καταλαμβάνουν 4 bytes μνήμης."; }		case LanguageType::HUNGARIAN:				{ return "Miért van ez az +4 a +1 helyett? Ez azért van, mert a nyomon követhető számok egész számok, amelyek 4 bájtnyi memóriát foglalnak magukban."; }
			case LanguageType::ITALIAN:					{ return "Perché questa +4 invece di +1? Questo perché i numeri tracciati sono numeri interi, che occupano 4 byte di memoria."; }		case LanguageType::JAPANESE:				{ return "これはなぜ+1の代わりに+4なのですか？これは、追跡されている数字が整数であり、4バイトのメモリを消費するためです。"; }
			case LanguageType::KOREAN:					{ return "+1가 아닌 왜 +4입니까? 이것은 추적되는 숫자가 4 바이트의 메모리를 차지하는 정수이기 때문입니다."; }		case LanguageType::NORWEGIAN:				{ return "Hvorfor er dette +4 i stedet for +1? Dette skyldes at tallene som spores, er heltall, som tar opp 4 bytes minne."; }
			case LanguageType::POLISH:					{ return "Dlaczego ten +4 zamiast +1? Dzieje się tak, ponieważ śledzone liczby są liczbami całkowitymi, które zajmują 4 bajty pamięci."; }		case LanguageType::PORTUGUESE:				{ return "Por que isso é +4 em vez de +1? Isso ocorre porque os números que estão sendo rastreados são inteiros, que ocupam 4 bytes de memória."; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Por que isso é +4 em vez de +1? Isso ocorre porque os números que estão sendo rastreados são inteiros, que ocupam 4 bytes de memória."; }		case LanguageType::ROMANIAN:				{ return "De ce este acest +4 în loc de +1? Acest lucru se datorează faptului că numerele care sunt urmărite sunt numere întregi, care ocupă 4 octeți de memorie."; }
			case LanguageType::RUSSIAN:					{ return "Почему этот +4 вместо +1? Это связано с тем, что отслеживаемые числа являются целыми числами, которые занимают 4 байта памяти."; }		case LanguageType::SPANISH:					{ return "¿Por qué es este +4 en lugar de +1? Esto se debe a que los números que se rastrean son enteros, que ocupan 4 bytes de memoria."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "¿Por qué es este +4 en lugar de +1? Esto se debe a que los números que se rastrean son enteros, que ocupan 4 bytes de memoria."; }	case LanguageType::SWEDISH:					{ return "Varför är det här +4 istället för +1? Detta beror på att numren som spåras är heltal, som tar upp 4 byte minne."; }
			case LanguageType::THAI:					{ return "ทำไม +4 นี้แทน +1 นี่เป็นเพราะตัวเลขที่ถูกติดตามเป็นจำนวนเต็มซึ่งใช้หน่วยความจำ 4 ไบต์"; }		case LanguageType::TURKISH:					{ return "Neden +1 yerine bu +4? Bunun nedeni, izlenen sayıların 4 byte belleği kaplayan tamsayılar olmasıdır."; }
			case LanguageType::UKRAINIAN:				{ return "Чому цей +4 замість +1? Це відбувається тому, що відстежені числа - цілі числа, які займають 4 байти пам'яті."; }		case LanguageType::VIETNAMESE:				{ return "Tại sao +4 này thay vì +1? Điều này là do các số được theo dõi là số nguyên, chiếm 4 byte bộ nhớ."; }
			default: case LanguageType::ENGLISH:		{ return "Why is this +4 instead of +1? This is because the numbers being tracked are integers, which take up 4 bytes of memory."; }
		}
	}
