	std::string Menus_Hacking_Lexicon_Pages_Data_OffsetHelp8::getStringByLanguage(LanguageType languageType)
	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return ".لماذا هذا +8 بدلا من +2؟ وذلك لأن الأرقام التي يتم تعقبها هي أعداد صحيحة ، والتي تستهلك 4 بايتات من الذاكرة لكل منها ، لذا فإن اثنين من هذه الأرقام يصنعان 8 بايتات في المجموع"; }		case LanguageType::BULGARIAN:				{ return "Защо това е +8 вместо +2? Това е така, защото проследените числа са цели числа, които заемат по 4 байта всяка памет, така че две от тях са общо 8 байта."; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "为什么这是+8而不是+2？这是因为被跟踪的数字是整数，每个占用4个字节的内存，因此其中两个共计8个字节。"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "為什麼這是+8而不是+2？這是因為被跟踪的數字是整數，每個佔用4個字節的內存，因此其中兩個共計8個字節。"; }
			case LanguageType::CZECH:					{ return "Proč je tento +8 místo +2? Důvodem je, že sledovaná čísla jsou celá čísla, která zabírají 4 bajty paměti, takže dvě z nich tvoří celkem 8 bajtů."; }		case LanguageType::DANISH:					{ return "Hvorfor er dette +8 i stedet for +2? Dette skyldes, at de tal, der spores, er heltal, der optager 4 bytes hukommelse hver, så to af disse giver 8 byte i alt."; }
			case LanguageType::DUTCH:					{ return "Waarom is dit +8 in plaats van +2? Dit komt omdat de getallen die geteld worden, gehele getallen zijn, die elk 4 bytes geheugen innemen, dus twee hiervan maken in totaal 8 bytes."; }		case LanguageType::FINNISH:					{ return "Miksi tämä +8 sijasta +2? Tämä johtuu siitä, että seurattavat numerot ovat kokonaislukuja, jotka vievät 4 tavua muistia, joten kaksi näistä muodostaa yhteensä 8 tavua."; }
			case LanguageType::FRENCH:					{ return "Pourquoi est-ce +8 au lieu de +2? Cela est dû au fait que les nombres suivis sont des entiers, qui occupent chacun 4 octets de mémoire. Par conséquent, deux d'entre eux représentent 8 octets au total."; }		case LanguageType::GERMAN:					{ return "Warum ist das +8 statt +2? Dies liegt daran, dass die verfolgten Zahlen Ganzzahlen sind, die jeweils 4 Byte Speicher belegen, sodass zwei davon insgesamt 8 Byte ergeben."; }
			case LanguageType::GREEK:					{ return "Γιατί είναι αυτό +8 αντί για +2; Αυτό οφείλεται στο γεγονός ότι οι αριθμοί που παρακολουθούνται είναι ακέραιοι αριθμοί, οι οποίοι καταλαμβάνουν 4 byte μνήμης το καθένα, έτσι ώστε δύο από αυτά να κάνουν 8 bytes συνολικά."; }		case LanguageType::HUNGARIAN:				{ return "Miért ez a +8 a +2 helyett? Ez azért van, mert a nyomon követhető számok egész számok, amelyek mindegyike 4 bájtnyi memóriát foglal magába, így kettő összesen 8 bájtot tesz ki."; }
			case LanguageType::ITALIAN:					{ return "Perché questo è +8 anziché +2? Questo perché i numeri tracciati sono numeri interi, che occupano ciascuno 4 byte di memoria, quindi due di questi rendono 8 byte in totale."; }		case LanguageType::JAPANESE:				{ return "なぜこれが+2ではなく+8なのでしょうか。これは、追跡されている数値が整数で、それぞれ4バイトのメモリを占有するため、これらのうち2つが合計8バイトになるためです。"; }
			case LanguageType::KOREAN:					{ return "왜이 대신 +8 대신 +8입니까? 이것은 추적되는 숫자가 각각 4 바이트의 메모리를 차지하는 정수이기 때문에 두 개가 총 8 바이트가되기 때문입니다."; }		case LanguageType::NORWEGIAN:				{ return "Hvorfor er dette +8 i stedet for +2? Dette skyldes at tallene som spores er heltall, som tar opp 4 bytes minne hver, slik at to av disse gir 8 byte totalt."; }
			case LanguageType::POLISH:					{ return "Dlaczego to +8 zamiast +2? Dzieje się tak, ponieważ śledzone liczby są liczbami całkowitymi, które zajmują po 4 bajty pamięci, więc dwa z nich tworzą łącznie 8 bajtów."; }		case LanguageType::PORTUGUESE:				{ return "Por que isso é +8 em vez de +2? Isso ocorre porque os números que estão sendo rastreados são inteiros, que ocupam 4 bytes de memória cada, portanto, dois deles totalizam 8 bytes."; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Por que isso é +8 em vez de +2? Isso ocorre porque os números que estão sendo rastreados são inteiros, que ocupam 4 bytes de memória cada, portanto, dois deles totalizam 8 bytes."; }		case LanguageType::ROMANIAN:				{ return "De ce este acest +8 în loc de +2? Acest lucru se datorează faptului că numerele care sunt urmărite sunt numere întregi, care ocupă câte 4 octeți de memorie fiecare, astfel că două dintre acestea fac 8 octeți în total."; }
			case LanguageType::RUSSIAN:					{ return "Почему это +8 вместо +2? Это связано с тем, что отслеживаемые числа являются целыми числами, каждый из которых занимает 4 байта памяти, поэтому два из них составляют в общей сложности 8 байтов."; }		case LanguageType::SPANISH:					{ return "¿Por qué es este +8 en lugar de +2? Esto se debe a que los números que se rastrean son enteros, que ocupan 4 bytes de memoria cada uno, por lo que dos de ellos forman 8 bytes en total."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "¿Por qué es este +8 en lugar de +2? Esto se debe a que los números que se rastrean son enteros, que ocupan 4 bytes de memoria cada uno, por lo que dos de ellos forman 8 bytes en total."; }	case LanguageType::SWEDISH:					{ return "Varför är detta +8 istället för +2? Detta beror på att numren som spåras är heltal, som tar upp 4 byte minne varje, så två av dessa gör 8 byte totalt."; }
			case LanguageType::THAI:					{ return "ทำไม +8 ถึง +2? นี่เป็นเพราะตัวเลขที่ถูกติดตามเป็นจำนวนเต็มซึ่งใช้หน่วยความจำ 4 ไบต์ต่อหน่วยดังนั้นสองในจำนวนนี้จึงรวมเป็น 8 ไบต์"; }		case LanguageType::TURKISH:					{ return "Neden bu +8, +2 yerine? Bunun nedeni, izlenen sayıların her biri 4 byte'lık bellek alan tam sayılar olması, bunlardan iki tanesinin toplamda 8 byte olması."; }
			case LanguageType::UKRAINIAN:				{ return "Чому це +8 замість +2? Це пояснюється тим, що відстежувані числа - цілі числа, які займають по 4 байти пам'яті кожен, тому два з них складають загалом 8 байт."; }		case LanguageType::VIETNAMESE:				{ return "Tại sao đây là +8 thay vì +2? Điều này là do các số được theo dõi là số nguyên, chiếm 4 byte bộ nhớ mỗi số, vì vậy hai trong số này tạo ra tổng cộng 8 byte."; }
			default: case LanguageType::ENGLISH:		{ return "Why is this +8 instead of +2? This is because the numbers being tracked are integers, which take up 4 bytes of memory each, so two of these makes 8 bytes in total."; }
		}
	}
