	std::string Menus_Party_StuckConfirm::getStringByLanguage(LanguageType languageType)
	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return "إذا علقت ، سيحاول ذلك إعادة تحميل الخريطة. تقدم؟"; }		case LanguageType::BULGARIAN:				{ return "Ако сте заседнали, това ще се опита да презареди картата. Ли да продължите?"; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "如果您卡住了，这将尝试重新加载地图。继续？"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "如果您卡住了，這將嘗試重新加載地圖。繼續？"; }
			case LanguageType::CZECH:					{ return "Pokud jste uvízli, pokusí se znovu načíst mapu. Pokračovat?"; }		case LanguageType::DANISH:					{ return "Hvis du sidder fast, forsøger dette at genindlæse kortet. Fortsæt?"; }
			case LanguageType::DUTCH:					{ return "Als je vastzit, zal dit proberen de kaart opnieuw te laden. Doorgaan?"; }		case LanguageType::FINNISH:					{ return "Jos olet jumissa, tämä yrittää ladata kartan uudelleen. Edetä?"; }
			case LanguageType::FRENCH:					{ return "Si vous êtes bloqué, cela tentera de recharger la carte. Procéder?"; }		case LanguageType::GERMAN:					{ return "Wenn Sie nicht weiterkommen, wird versucht, die Karte neu zu laden. Vorgehen?"; }
			case LanguageType::GREEK:					{ return "Εάν έχετε κολλήσει, αυτό θα προσπαθήσει να φορτώσει ξανά τον χάρτη. Προχωρώ?"; }		case LanguageType::HUNGARIAN:				{ return "Ha elakad, akkor megpróbálja újból betölteni a térképet. Folytassa?"; }
			case LanguageType::ITALIAN:					{ return "Se rimani bloccato, questo tenterà di ricaricare la mappa. Procedere?"; }		case LanguageType::JAPANESE:				{ return "行き詰まっている場合は、マップの再読み込みを試みます。続行しますか？"; }
			case LanguageType::KOREAN:					{ return "붙어 있으면지도를 다시로드하려고 시도합니다. 발하다?"; }		case LanguageType::NORWEGIAN:				{ return "Hvis du sitter fast, vil dette prøve å laste inn kartet på nytt. Fortsette?"; }
			case LanguageType::POLISH:					{ return "Jeśli utkniesz, nastąpi próba ponownego załadowania mapy. Kontynuować?"; }		case LanguageType::PORTUGUESE:				{ return "Se você estiver travado, isso tentará recarregar o mapa. Continuar?"; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Se você estiver travado, isso tentará recarregar o mapa. Continuar?"; }		case LanguageType::ROMANIAN:				{ return "Dacă sunteți blocat, acest lucru va încerca să reîncărcați harta. Continua?"; }
			case LanguageType::RUSSIAN:					{ return "Если вы застряли, это попытается перезагрузить карту. Продолжить?"; }		case LanguageType::SPANISH:					{ return "Si está atascado, esto intentará volver a cargar el mapa. ¿Continuar?"; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "Si está atascado, esto intentará volver a cargar el mapa. ¿Continuar?"; }	case LanguageType::SWEDISH:					{ return "Om du sitter fast försöker du ladda kartan igen. Fortsätt?"; }
			case LanguageType::THAI:					{ return "หากคุณติดอยู่นี่จะพยายามโหลดแผนที่ใหม่ ดำเนินดำเนินการต่อ?"; }		case LanguageType::TURKISH:					{ return "Sıkışırsanız, haritayı yeniden yüklemeye çalışır. İlerlemek?"; }
			case LanguageType::UKRAINIAN:				{ return "Якщо ви застрягли, це спробує перезавантажити карту. Продовжувати?"; }		case LanguageType::VIETNAMESE:				{ return "Nếu bạn bị kẹt, điều này sẽ cố tải lại bản đồ. Tiến hành?"; }
			default: case LanguageType::ENGLISH:		{ return "If you are stuck, this will attempt to reload the map. Proceed?"; }
		}
	}
