	std::string Platformer_Dialogue_Recruitable_GuanoRecruitable::getStringByLanguage(LanguageType languageType)
	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return "اسمحوا لي أن أخمن ، هل تحتاج إلي لمساعدتك مرة أخرى؟"; }		case LanguageType::BULGARIAN:				{ return "Да предположим, че имате нужда от мен, за да ви помогна отново?"; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "让我猜猜，你需要我再次帮助你吗？"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "讓我猜猜，你需要我再次説明你嗎？"; }
			case LanguageType::CZECH:					{ return "Dovolte mi hádat, potřebujete, abych vám znovu pomohl?"; }		case LanguageType::DANISH:					{ return "Lad mig gætte, du har brug for mig til at hjælpe dig igen?"; }
			case LanguageType::DUTCH:					{ return "Laat me raden, je hebt me nodig om je weer te helpen?"; }		case LanguageType::FINNISH:					{ return "Anna minun arvata, tarvitsetko minua auttamaan sinua uudelleen?"; }
			case LanguageType::FRENCH:					{ return "Laissez-moi deviner, vous avez besoin de moi pour vous aider à nouveau?"; }		case LanguageType::GERMAN:					{ return "Lass mich raten, du brauchst mich, um dir wieder zu helfen?"; }
			case LanguageType::GREEK:					{ return "Επιτρέψτε μου να μαντέψω, χρειάζεστε να σας βοηθήσω ξανά;"; }		case LanguageType::HUNGARIAN:				{ return "Hadd találjam ki, szükséged van rám, hogy újra segítsek neked?"; }
			case LanguageType::ITALIAN:					{ return "Fammi indovinare, hai bisogno che ti aiuti di nuovo?"; }		case LanguageType::JAPANESE:				{ return "私に推測させてください、あなたは私が再びあなたを助けるために必要ですか?"; }
			case LanguageType::KOREAN:					{ return "내가 추측하자, 너는 너를 다시 도울 필요가 있니?"; }		case LanguageType::NORWEGIAN:				{ return "La meg gjette, trenger du meg til å hjelpe deg ut igjen?"; }
			case LanguageType::POLISH:					{ return "Pozwól mi zgadnąć, potrzebujesz mnie, abym ci pomógł ponownie?"; }		case LanguageType::PORTUGUESE:				{ return "Deixe-me adivinhar, precisa de mim para ajudá-lo de novo?"; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Deixe-me adivinhar, você precisa de mim para ajudá-lo novamente?"; }		case LanguageType::ROMANIAN:				{ return "Lasă-mă să ghicesc, ai nevoie de mine pentru a vă ajuta din nou?"; }
			case LanguageType::RUSSIAN:					{ return "Позвольте мне догадаться, вам нужно, чтобы я снова помог вам?"; }		case LanguageType::SPANISH:					{ return "Déjame adivinar, ¿necesitas que te ayude de nuevo?"; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "Déjame adivinar, ¿necesitas que te ayude de nuevo?"; }	case LanguageType::SWEDISH:					{ return "Låt mig gissa, behöver du mig för att hjälpa dig igen?"; }
			case LanguageType::THAI:					{ return "ให้ฉันเดาคุณต้องการให้ฉันช่วยคุณออกอีกครั้ง?"; }		case LanguageType::TURKISH:					{ return "Tahmin edeyim, sana tekrar yardım etmem için bana mı ihtiyacın var?"; }
			case LanguageType::UKRAINIAN:				{ return "Дозвольте мені здогадатися, вам потрібно, щоб я знову допоміг вам?"; }		case LanguageType::VIETNAMESE:				{ return "Hãy để tôi đoán, bạn cần tôi giúp bạn một lần nữa?"; }
			default: case LanguageType::ENGLISH:		{ return "Let me guess, you need me to help you out again?"; }
		}
	}
