	std::string Platformer_Help_HelpTotemGecky::getStringByLanguage(LanguageType languageType)
	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return ".يمكن إصلاح بعض الكائنات. إذا كان %s1 في مجموعتك، فاضغط باستمرار على %s2 وانقر لإصلاح الكائن"; }		case LanguageType::BULGARIAN:				{ return "Някои обекти могат да бъдат поправени. Ако %s1 е във вашата страна, задръжте %s2 и щракнете, за да поправите обекта."; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "有些物体是可以修复的。如果 %s1 在您的群中，请按住 %s2 并单击以修复对象。"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "有些物體是可以修復的。如果 %s1 在您的群中，請按住 %s2 並按下以修復物件。"; }
			case LanguageType::CZECH:					{ return "Některé objekty lze opravit. Pokud je %s1 ve vaší skupině, podržte %s2 a kliknutím objekt opravte."; }		case LanguageType::DANISH:					{ return "Nogle genstande kan repareres. Hvis %s1 er i din gruppe, skal du holde %s2 nede og klikke for at reparere objektet."; }
			case LanguageType::DUTCH:					{ return "Sommige objecten kunnen worden gerepareerd. Als %s1 zich in uw party bevindt, houdt u %s2 ingedrukt en klikt u om het object te repareren."; }		case LanguageType::FINNISH:					{ return "Jotkut esineet voidaan korjata. Jos %s1 on seurueessasi, pidä %s2-näppäintä painettuna ja korjaa objekti napsauttamalla."; }
			case LanguageType::FRENCH:					{ return "Certains objets peuvent être réparés. Si %s1 est dans votre groupe, maintenez %s2 et cliquez pour réparer l’objet."; }		case LanguageType::GERMAN:					{ return "Einige Objekte können repariert werden. Wenn sich %s1 in Ihrer Gruppe befindet, halten Sie %s2 gedrückt und klicken Sie, um das Objekt zu reparieren."; }
			case LanguageType::GREEK:					{ return "Ορισμένα αντικείμενα μπορούν να επισκευαστούν. Εάν το %s1 βρίσκεται στο γκρουπ σας, κρατήστε πατημένο το %s2 και κάντε κλικ για να επιδιορθώσετε το αντικείμενο."; }		case LanguageType::HUNGARIAN:				{ return "Egyes tárgyak javíthatók. Ha az %s1 az Ön pártjában van, tartsa lenyomva a %s2-t, és kattintson az objektum javításához."; }
			case LanguageType::ITALIAN:					{ return "Alcuni oggetti possono essere riparati. Se %s1 è nel tuo gruppo, tieni premuto %s2 e fai clic per riparare l'oggetto."; }		case LanguageType::JAPANESE:				{ return "一部のオブジェクトは修復できます。%s1 がパーティーに参加している場合は、%s2 を押しながらクリックしてオブジェ クトを修復します。"; }
			case LanguageType::KOREAN:					{ return "일부 개체는 복구할 수 있습니다. %s1가 파티에 있는 경우 %s2를 누른 상태에서 클릭하여 개체를 복구합니다."; }		case LanguageType::NORWEGIAN:				{ return "Noen objekter kan repareres. Hvis %s1 er i festen, holder du %s2 og klikker for å reparere objektet."; }
			case LanguageType::POLISH:					{ return "Niektóre obiekty można naprawić. Jeśli %s1 jest w twojej grupie, przytrzymaj %s2 i kliknij, aby naprawić obiekt."; }		case LanguageType::PORTUGUESE:				{ return "Alguns objetos podem ser reparados. Se a %s1 estiver na sua festa, segure a %s2 e clique para reparar o objeto."; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Alguns objetos podem ser reparados. Se o %s1 estiver na sua festa, segure o %s2 e clique para reparar o objeto."; }		case LanguageType::ROMANIAN:				{ return "Unele obiecte pot fi reparate. Dacă %s1 este în partidul dvs., țineți apăsat %s2 și faceți clic pentru a repara obiectul."; }
			case LanguageType::RUSSIAN:					{ return "Некоторые объекты могут быть отремонтированы. Если %s1 находится в вашей группе, удерживайте %s2 и нажмите, чтобы восстановить объект."; }		case LanguageType::SPANISH:					{ return "Algunos objetos pueden ser reparados. Si %s1 está en su grupo, mantenga presionado %s2 y haga clic para reparar el objeto."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "Algunos objetos pueden ser reparados. Si %s1 está en su grupo, mantenga presionado %s2 y haga clic para reparar el objeto."; }	case LanguageType::SWEDISH:					{ return "Vissa föremål kan repareras. Om %s1 är i ditt sällskap, håll %s2 och klicka för att reparera objektet."; }
			case LanguageType::THAI:					{ return "วัตถุบางอย่างสามารถซ่อมแซมได้ ถ้า %s1 อยู่ในพรรคของคุณให้กด %s2 ค้างไว้และคลิกเพื่อซ่อมแซมวัตถุ"; }		case LanguageType::TURKISH:					{ return "Bazı nesneler onarılabilir. %s1 grubunuzda ise, %s2 tuşunu basılı tutun ve nesneyi onarmak için tıklayın."; }
			case LanguageType::UKRAINIAN:				{ return "Деякі об'єкти можуть бути відремонтовані. Якщо %s1 у вашій партії, утримуйте %s2 і натисніть, щоб відремонтувати об'єкт."; }		case LanguageType::VIETNAMESE:				{ return "Một số đối tượng có thể được sửa chữa. Nếu %s1 nằm trong nhóm của bạn, hãy giữ %s2 và nhấp để sửa chữa đối tượng."; }
			default: case LanguageType::ENGLISH:		{ return "Some objects can be repaired. If %s1 is in your party, hold %s2 and click to repair the object."; }
		}
	}
