	std::string Platformer_Help_HelpTotemGrim::getStringByLanguage(LanguageType languageType)
	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return "!إذا كان %s1 في حفلتك ، فاضغط مع الاستمرار على %s2 وانقر على الأعداء القتلى لحصاد أرواحهم واستعادة بعض المانا والصحة"; }		case LanguageType::BULGARIAN:				{ return "Ако %s1 е във вашата партия, задръжте %s2 и кликнете върху мъртви врагове, за да съберете душите им и да възстановите малко мана и здраве!"; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "如果%s1在你的队伍中，请按住%s2并点击死去的敌人以收割他们的灵魂并恢复一些法力和生命值！"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "如果%s1在你的隊伍中，請按住%s2並點擊死去的敵人以收割他們的靈魂並恢復一些法力和生命值！"; }
			case LanguageType::CZECH:					{ return "Pokud je %s1 ve vaší skupině, držte %s2 a klikněte na mrtvé nepřátele, abyste získali jejich duše a obnovili nějakou manu a zdraví!"; }		case LanguageType::DANISH:					{ return "Hvis %s1 er i din gruppe, skal du holde %s2 og klikke på døde fjender for at høste deres sjæle og genoprette noget mana og sundhed!"; }
			case LanguageType::DUTCH:					{ return "Als %s1 in je groep zit, houd dan %s2 vast en klik op dode vijanden om hun ziel te oogsten en wat mana en gezondheid te herstellen!"; }		case LanguageType::FINNISH:					{ return "Jos %s1 on puolueessasi, pidä %s2 ja napsauta kuolleita vihollisia korjataksesi heidän sielunsa ja palauttaaksesi manaa ja terveyttä!"; }
			case LanguageType::FRENCH:					{ return "Si %s1 est dans votre groupe, tenez %s2 et cliquez sur les ennemis morts pour récolter leurs âmes et restaurer du mana et de la santé!"; }		case LanguageType::GERMAN:					{ return "Wenn %s1 in deiner Gruppe ist, halte %s2 gedrückt und klicke auf tote Feinde, um ihre Seelen zu ernten und etwas Mana und Gesundheit wiederherzustellen!"; }
			case LanguageType::GREEK:					{ return "Εάν το %s1 είναι στην ομάδα σας, κρατήστε το %s2 και κάντε κλικ σε νεκρούς εχθρούς για να μαζέψετε τις ψυχές τους και να αποκαταστήσετε λίγη μάνα και υγεία!"; }		case LanguageType::HUNGARIAN:				{ return "Ha %s1 a pártodban van, tartsd lenyomva a %s2-t, és kattints a halott ellenségekre, hogy begyűjtsd a lelküket, és helyreállíts némi manát és egészséget!"; }
			case LanguageType::ITALIAN:					{ return "Se %s1 è nel tuo gruppo, tieni %s2 e fai clic sui nemici morti per raccogliere le loro anime e ripristinare un po 'di mana e salute!"; }		case LanguageType::JAPANESE:				{ return "%s1がパーティーに参加している場合は、%s2を押したまま死んだ敵をクリックして魂を収穫し、マナと体力を回復します!"; }
			case LanguageType::KOREAN:					{ return "파티에 %s1가 있으면 %s2를 잡고 죽은 적을 클릭하여 영혼을 수확하고 마나와 체력을 회복하세요!"; }		case LanguageType::NORWEGIAN:				{ return "Hvis %s1 er i festen din, hold %s2 og klikk på døde fiender for å høste sjelene deres og gjenopprette litt mana og helse!"; }
			case LanguageType::POLISH:					{ return "Jeśli %s1 jest w twojej drużynie, trzymaj %s2 i klikaj na martwych wrogów, aby zebrać ich dusze i przywrócić trochę many i zdrowia!"; }		case LanguageType::PORTUGUESE:				{ return "Se %s1 estiver em seu grupo, segure %s2 e clique em inimigos mortos para colher suas almas e restaurar um pouco de mana e saúde!"; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Se %s1 estiver em seu grupo, segure %s2 e clique em inimigos mortos para colher suas almas e restaurar um pouco de mana e saúde!"; }		case LanguageType::ROMANIAN:				{ return "În cazul în care %s1 este în partidul tău, țineți %s2 și faceți clic pe dușmani morți pentru a recolta sufletele lor și de a restabili unele mana si sanatate!"; }
			case LanguageType::RUSSIAN:					{ return "Если %s1 находится в вашей группе, удерживайте %s2 и нажимайте на мертвых врагов, чтобы собрать их души и восстановить немного маны и здоровья!"; }		case LanguageType::SPANISH:					{ return "Si %s1 está en tu grupo, ¡mantén %s2 y haz clic en enemigos muertos para cosechar sus almas y restaurar algo de maná y salud!"; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "Si %s1 está en tu grupo, ¡mantén %s2 y haz clic en enemigos muertos para cosechar sus almas y restaurar algo de maná y salud!"; }	case LanguageType::SWEDISH:					{ return "Om %s1 är i ditt parti, håll %s2 och klicka på döda fiender för att skörda sina själar och återställa lite mana och hälsa!"; }
			case LanguageType::THAI:					{ return "หาก %s1 อยู่ในปาร์ตี้ของคุณให้ถือ %s2 และคลิกที่ศัตรูที่ตายแล้วเพื่อเก็บเกี่ยววิญญาณของพวกเขาและฟื้นฟูมานาและสุขภาพ!"; }		case LanguageType::TURKISH:					{ return "%s1 partinizdeyse, %s2'yi tutun ve ruhlarını toplamak ve biraz mana ve sağlığı geri kazanmak için ölü düşmanlara tıklayın!"; }
			case LanguageType::UKRAINIAN:				{ return "Якщо %s1 у вашій партії, утримуйте %s2 і натискайте на мертвих ворогів, щоб зібрати їхні душі та відновити трохи мани та здоров'я!"; }		case LanguageType::VIETNAMESE:				{ return "Nếu %s1 ở trong nhóm của bạn, hãy giữ %s2 và nhấp vào kẻ thù đã chết để thu hoạch linh hồn của chúng và khôi phục một số mana và máu!"; }
			default: case LanguageType::ENGLISH:		{ return "If %s1 is in your party, hold %s2 and click on dead enemies to harvest their souls and restore some mana and health!"; }
		}
	}
