			case LanguageType::DUTCH:					{ return "Hoe durfde ik mijn gezicht te laten zien nadat ik zo'n lafaard was? Ik denk dat ik verborgen blijf in de muren."; }		case LanguageType::FINNISH:					{ return "Kuinka uskalsin näyttää kasvoni, kun olin niin pelkuri? Taidan pysyä piilossa seinissä."; }
			case LanguageType::FRENCH:					{ return "Comment pourrais-je oser montrer mon visage après avoir été un tel lâche ? Je pense que je vais rester caché dans les murs."; }		case LanguageType::GERMAN:					{ return "Wie konnte ich es wagen, mein Gesicht zu zeigen, nachdem ich so ein Feigling war? Ich denke, ich werde mich in den Wänden verstecken."; }
			case LanguageType::GREEK:					{ return "Πώς θα τολμούσα να δείξω το πρόσωπό μου αφού ήμουν τόσο δειλός; Νομίζω ότι θα μείνω κρυμμένος στους τοίχους."; }		case LanguageType::HUNGARIAN:				{ return "Hogyan merhettem megmutatni az arcom, miután ilyen gyáva voltam? Azt hiszem, rejtve maradok a falak között."; }
			case LanguageType::ITALIAN:					{ return "Come potevo osare mostrare la mia faccia dopo essere stato un tale codardo? Penso che rimarrò nascosto tra i muri."; }		case LanguageType::JAPANESE:				{ return "そのような臆病者になった後、どうすればあえて顔を見せることができますか?私は壁に隠れたままだと思います。"; }
			case LanguageType::KOREAN:					{ return "그런 겁쟁이가 된 내가 어떻게 감히 내 얼굴을 드러낼 수 있겠는가? 벽에 숨어있을 것 같아요."; }		case LanguageType::NORWEGIAN:				{ return "Hvordan kunne jeg våge å vise ansiktet mitt etter å ha vært så feig? Jeg tror jeg vil holde meg skjult i veggene."; }
			case LanguageType::POLISH:					{ return "Jak mogłem odważyć się pokazać swoją twarz po tym, jak byłem takim tchórzem? Myślę, że pozostanę ukryty w ścianach."; }		case LanguageType::PORTUGUESE:				{ return "Como eu poderia ousar mostrar meu rosto depois de ser tão covarde? Acho que vou ficar escondido nas paredes."; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Como eu poderia ousar mostrar meu rosto depois de ser tão covarde? Acho que vou ficar escondido nas paredes."; }		case LanguageType::ROMANIAN:				{ return "Cum aș putea îndrăzni să-mi arăt fața după ce am fost atât de laș? Cred că voi rămâne ascuns în ziduri."; }
			case LanguageType::RUSSIAN:					{ return "Как я мог осмелиться показать свое лицо после того, как был таким трусом? Я думаю, что останусь спрятанным в стенах."; }		case LanguageType::SPANISH:					{ return "¿Cómo podría atreverme a mostrar mi cara después de ser tan cobarde? Creo que me quedaré escondido en las paredes."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "¿Cómo podría atreverme a mostrar mi cara después de ser tan cobarde? Creo que me quedaré escondido en las paredes."; }	case LanguageType::SWEDISH:					{ return "Hur kunde jag våga visa mitt ansikte efter att ha varit en sådan fegis? Jag tror att jag kommer att hålla mig gömd i väggarna."; }
			case LanguageType::THAI:					{ return "ฉันจะกล้าแสดงใบหน้าของฉันได้อย่างไรหลังจากเป็นคนขี้ขลาดเช่นนี้? ฉันคิดว่าฉันจะซ่อนตัวอยู่ในกําแพง"; }		case LanguageType::TURKISH:					{ return "Böyle bir korkak olduktan sonra yüzümü göstermeye nasıl cesaret edebilirim? Sanırım duvarlarda gizli kalacağım."; }
			case LanguageType::UKRAINIAN:				{ return "Як я міг наважитися показати своє обличчя після того, як був таким боягузом? Я думаю, що залишуся схованим у стінах."; }		case LanguageType::VIETNAMESE:				{ return "Làm sao tôi dám lộ mặt sau khi trở thành một kẻ hèn nhát như vậy? Tôi nghĩ tôi sẽ ẩn mình trong những bức tường."; }
