	std::string Platformer_Quests_DataMines_RestorePower_PrincessDawn_K_ImOut::getStringByLanguage(LanguageType languageType)
	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return ".يبدو أنكم جميعا قد غطيتم كل شيء ، وأنا آخذ استراحة. سأكون في النزل إذا كنت بحاجة إلي"; }		case LanguageType::BULGARIAN:				{ return "Изглежда, че всички имате всичко покрито, взимам си почивка. Аз ще бъда в хана, ако имате нужда от мен."; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "似乎你们都涵盖了一切，我正在休息。如果你需要我，我会在客栈。"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "似乎你們都涵蓋了一切，我正在休息。如果你需要我，我會在客棧。"; }
			case LanguageType::CZECH:					{ return "Zdá se, že všichni máte všechno pokryté, dávám si pauzu. Budu v hostinci, jestli mě budeš potřebovat."; }		case LanguageType::DANISH:					{ return "Det ser ud til, at I alle har alt dækket, jeg tager en pause. Jeg vil være på kroen, hvis du har brug for mig."; }
			case LanguageType::DUTCH:					{ return "Het lijkt alsof jullie allemaal alles gedekt hebben, ik neem een pauze. Ik zal in de herberg zijn als je me nodig hebt."; }		case LanguageType::FINNISH:					{ return "Näyttää siltä, että teillä kaikilla on kaikki katettu, pidän tauon. Olen majatalossa, jos tarvitset minua."; }
			case LanguageType::FRENCH:					{ return "On dirait que vous avez tous tout couvert, je fais une pause. Je serai à l’auberge si vous avez besoin de moi."; }		case LanguageType::GERMAN:					{ return "Es scheint, als hättet ihr alle alles abgedeckt, ich mache eine Pause. Ich werde im Gasthaus sein, wenn Sie mich brauchen."; }
			case LanguageType::GREEK:					{ return "Φαίνεται ότι όλοι έχετε καλύψει τα πάντα, κάνω ένα διάλειμμα. Θα είμαι στο πανδοχείο αν με χρειαστείτε."; }		case LanguageType::HUNGARIAN:				{ return "Úgy tűnik, hogy mindannyian mindent lefedtek, szünetet tartok. A fogadóban leszek, ha szükséged van rám."; }
			case LanguageType::ITALIAN:					{ return "Sembra che tutti voi abbiate tutto coperto, mi sto prendendo una pausa. Sarò alla locanda se hai bisogno di me."; }		case LanguageType::JAPANESE:				{ return "皆さんは全てを網羅しているようで、ちょっと休憩しています。あなたが私を必要とするなら、私は旅館にいます。"; }
			case LanguageType::KOREAN:					{ return "여러분 모두가 모든 것을 덮은 것처럼 보입니다, 나는 휴식을 취하고 있습니다. 당신이 나를 필요로한다면 나는 여관에있을 것입니다."; }		case LanguageType::NORWEGIAN:				{ return "Det virker som om dere alle har alt dekket, jeg tar en pause. Jeg er på vertshuset hvis du trenger meg."; }
			case LanguageType::POLISH:					{ return "Wygląda na to, że wszyscy macie wszystko pod kontrolą, robię sobie przerwę. Będę w gospodzie, jeśli mnie potrzebujesz."; }		case LanguageType::PORTUGUESE:				{ return "Parece que todos têm tudo coberto, estou a fazer uma pausa. Estarei na estalagem, se precisar de mim."; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Parece que todos vocês têm tudo coberto, estou dando um tempo. Estarei na pousada se precisar de mim."; }		case LanguageType::ROMANIAN:				{ return "Se pare ca toti aveti totul acoperit, iau o pauza. Voi fi la han, dacă aveți nevoie de mine."; }
			case LanguageType::RUSSIAN:					{ return "Кажется, что у вас у всех есть все, я делаю перерыв. Я буду в гостинице, если я вам нужен."; }		case LanguageType::SPANISH:					{ return "Parece que todos ustedes tienen todo cubierto, me estoy tomando un descanso. Estaré en la posada si me necesitas."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "Parece que todos ustedes tienen todo cubierto, me estoy tomando un descanso. Estaré en la posada si me necesitas."; }	case LanguageType::SWEDISH:					{ return "Det verkar som om ni alla har allt täckt, jag tar en paus. Jag är på värdshuset om du behöver mig."; }
			case LanguageType::THAI:					{ return "ดูเหมือนว่าคุณทุกคนมีทุกอย่างที่ครอบคลุมฉันกําลังหยุดพัก ฉันจะอยู่ที่โรงแรมถ้าคุณต้องการฉัน"; }		case LanguageType::TURKISH:					{ return "Görünüşe göre hepiniz her şeyi kapsıyor, ara veriyorum. Bana ihtiyacın olursa handa olacağım."; }
			case LanguageType::UKRAINIAN:				{ return "Здається, у вас у всіх все покрито, я роблю перерву. Я буду в корчмі, якщо я тобі потрібен."; }		case LanguageType::VIETNAMESE:				{ return "Có vẻ như tất cả các bạn đều có mọi thứ được bảo hiểm, tôi đang nghỉ ngơi. Tôi sẽ ở nhà trọ nếu bạn cần tôi."; }
			default: case LanguageType::ENGLISH:		{ return "It seems like you all have everything covered, I'm taking a break. I'll be at the inn if you need me."; }
		}
	}
