			case LanguageType::RUSSIAN:					{ return "Электричество вернулось! Спасибо за ваши усилия."; }		case LanguageType::SPANISH:					{ return "¡La electricidad ha vuelto! Gracias por sus esfuerzos."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "¡La electricidad ha vuelto! Gracias por sus esfuerzos."; }	case LanguageType::SWEDISH:					{ return "Strömmen är tillbaka! Tack för era ansträngningar."; }
			case LanguageType::THAI:					{ return "ไฟฟ้ากลับมาแล้ว! ขอบคุณสำหรับความพยายามของคุณ"; }		case LanguageType::TURKISH:					{ return "Elektrik geri geldi! Çabalarınız için teşekkür ederiz."; }
			case LanguageType::UKRAINIAN:				{ return "Електрика повернулася! Дякую за ваші зусилля."; }		case LanguageType::VIETNAMESE:				{ return "Điện đã trở lại! Cảm ơn bạn vì những nỗ lực của bạn."; }
