	std::string Platformer_Quests_DataMines_RestorePower_PrincessDawn_R_TakeTrainTicket::getStringByLanguage(LanguageType languageType)
	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return ".أسرع طريقة للخروج من هذا المنجم هي بالقطار. خذ تذكرة القطار هذه ، ويمكنك استخدام قطاراتنا بشكل متكرر كما تريد"; }		case LanguageType::BULGARIAN:				{ return "Най-бързият изход от тази мина е с влак. Вземете този билет за влак и можете да използвате нашите влакове толкова често, колкото искате."; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "离开这个矿井最快的方法是乘火车。带上这张火车票，您可以根据需要经常使用我们的火车。"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "離開這個礦井最快的方法是乘火車。帶上這張火車票，您可以根據需要經常使用我們的火車。"; }
			case LanguageType::CZECH:					{ return "Nejrychlejší cesta z tohoto dolu je vlakem. Vezměte si tuto jízdenku na vlak a můžete používat naše vlaky tak často, jak chcete."; }		case LanguageType::DANISH:					{ return "Den hurtigste vej ud af denne mine er med tog. Tag denne togbillet, og du kan bruge vores tog så ofte som du vil."; }
			case LanguageType::DUTCH:					{ return "De snelste uitweg uit deze mijn is met de trein. Neem dit treinkaartje en u kunt onze treinen zo vaak gebruiken als u wilt."; }		case LanguageType::FINNISH:					{ return "Nopein tie ulos tästä kaivoksesta on junalla. Ota tämä junalippu, ja voit käyttää juniamme niin usein kuin haluat."; }
			case LanguageType::FRENCH:					{ return "Le moyen le plus rapide de sortir de cette mine est en train. Prenez ce billet de train, et vous pouvez utiliser nos trains aussi souvent que vous le souhaitez."; }		case LanguageType::GERMAN:					{ return "Der schnellste Weg aus dieser Mine heraus ist mit dem Zug. Nehmen Sie dieses Zugticket und Sie können unsere Züge so oft benutzen, wie Sie möchten."; }
			case LanguageType::GREEK:					{ return "Η πιο γρήγορη διέξοδος από αυτό το ορυχείο είναι με το τρένο. Πάρτε αυτό το εισιτήριο τρένου και μπορείτε να χρησιμοποιείτε τα τρένα μας όσο συχνά θέλετε."; }		case LanguageType::HUNGARIAN:				{ return "A leggyorsabb út ebből a bányából vonattal történik. Vegye igénybe ezt a vonatjegyet, és vonatainkat olyan gyakran használhatja, ahányszor csak akarja."; }
			case LanguageType::ITALIAN:					{ return "La via d'uscita più rapida da questa miniera è in treno. Prendi questo biglietto del treno e puoi utilizzare i nostri treni tutte le volte che vuoi."; }		case LanguageType::JAPANESE:				{ return "この鉱山から出る最も簡単な方法は電車です。この列車のチケットを取ると、あなたはあなたが望むだけ頻繁に私たちの 列車を使用することができます。"; }
			case LanguageType::KOREAN:					{ return "이 광산에서 가장 빠른 방법은 기차입니다. 이 기차 티켓을 타면 원하는만큼 자주 열차를 이용할 수 있습니다."; }		case LanguageType::NORWEGIAN:				{ return "Den raskeste veien ut av denne gruven er med tog. Ta denne togbilletten, og du kan bruke togene våre så ofte du vil."; }
			case LanguageType::POLISH:					{ return "Najszybszym wyjściem z tej kopalni jest pociąg. Weź ten bilet kolejowy i możesz korzystać z naszych pociągów tak często, jak chcesz."; }		case LanguageType::PORTUGUESE:				{ return "A saída mais rápida desta mina é de comboio. Pegue este bilhete de comboio e poderá usar nossos comboios com a frequência que quiser."; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "A maneira mais rápida de sair desta mina é de trem. Pegue esta passagem de trem, e você pode usar nossos trens com tanta frequência quanto quiser."; }		case LanguageType::ROMANIAN:				{ return "Cea mai rapidă cale de ieșire din această mină este cu trenul. Luați acest bilet de tren și puteți utiliza trenurile noastre cât de des doriți."; }
			case LanguageType::RUSSIAN:					{ return "Самый быстрый выход из этой шахты — на поезде. Возьмите этот билет на поезд, и вы можете использовать наши поезда так часто, как захотите."; }		case LanguageType::SPANISH:					{ return "La forma más rápida de salir de esta mina es en tren. Tome este boleto de tren y puede usar nuestros trenes con la frecuencia que desee."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "La forma más rápida de salir de esta mina es en tren. Tome este boleto de tren y puede usar nuestros trenes con la frecuencia que desee."; }	case LanguageType::SWEDISH:					{ return "Den snabbaste vägen ut ur denna gruva är med tåg. Ta denna tågbiljett, och du kan använda våra tåg så ofta du vill."; }
			case LanguageType::THAI:					{ return "วิธีที่เร็วที่สุดออกจากเหมืองนี้คือโดยรถไฟ ใช้ตั๋วรถไฟนี้, และคุณสามารถใช้รถไฟของเราบ่อยเท่าที่คุณต้องการ."; }		case LanguageType::TURKISH:					{ return "Bu madenden en hızlı çıkış yolu trenle. Bu tren biletini alın ve trenlerimizi istediğiniz sıklıkta kullanabilirsiniz."; }
			case LanguageType::UKRAINIAN:				{ return "Найшвидший вихід з цієї шахти - поїздом. Візьміть цей квиток на поїзд, і ви можете користуватися нашими поїздами так часто, як захочете."; }		case LanguageType::VIETNAMESE:				{ return "Cách nhanh nhất để thoát khỏi mỏ này là bằng tàu hỏa. Lấy vé tàu này và bạn có thể sử dụng tàu của chúng tôi thường xuyên như bạn muốn."; }
			default: case LanguageType::ENGLISH:		{ return "The quickest way out of this mine is by train. Take this train ticket, and you may use our trains as frequently as you want."; }
		}
	}
