	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return "يمكنني أيضًا مساعدتك إذا احتجتني يومًا ما لـ'العثور' على شيء في جيوب شخص ما من أجلك. الغوبلن أساتذة التخفي!"; }		case LanguageType::BULGARIAN:				{ return "Мога също да ти помогна, ако някога имаш нужда да 'намеря' нещо в нечии джобове за теб. Гоблините са майстори на прикриването!"; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "如果你哪天需要我帮你在别人的口袋里'找到'点什么，我也能帮上忙。哥布林可是潜行大师！"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "如果你哪天需要我幫你在別人的口袋裡'找到'些什麼，我也能幫上忙。哥布林可是潛行大師！"; }
			case LanguageType::CZECH:					{ return "Můžu ti také pomoct, pokud někdy budeš potřebovat, abych pro tebe v něčích kapsách něco 'našel'. Goblini jsou mistři plížení!"; }		case LanguageType::DANISH:					{ return "Jeg kan også hjælpe dig, hvis du nogensinde har brug for, at jeg 'finder' noget i nogens lommer for dig. Gobliner er mestre i snigen!"; }
			case LanguageType::DUTCH:					{ return "Ik kan je ook helpen als je me ooit nodig hebt om iets in iemands zakken voor je te 'vinden'. Goblins zijn meesters in sluipen!"; }		case LanguageType::FINNISH:					{ return "Voin myös auttaa sinua, jos joskus tarvitset minua 'löytämään' jotain jonkun taskuista puolestasi. Goblinit ovat hiivinnän mestareita!"; }
			case LanguageType::FRENCH:					{ return "Je peux aussi t'aider si tu as un jour besoin que je 'trouve' quelque chose dans les poches de quelqu'un pour toi. Les gobelins sont des maîtres de la furtivité !"; }		case LanguageType::GERMAN:					{ return "Ich kann dir auch helfen, wenn du mich jemals brauchst, um etwas in jemandes Taschen für dich zu 'finden'. Goblins sind Meister der Heimlichkeit!"; }
			case LanguageType::GREEK:					{ return "Μπορώ επίσης να σε βοηθήσω αν ποτέ με χρειαστείς να 'βρω' κάτι στις τσέπες κάποιου για σένα. Τα γκόμπλιν είναι μάστορες της κρυψίνοιας!"; }		case LanguageType::HUNGARIAN:				{ return "Én is segíthetek, ha valaha szükséged van rám, hogy 'megtaláljak' valamit valaki zsebében neked. A goblinok a lopakodás mesterei!"; }
			case LanguageType::ITALIAN:					{ return "Posso anche aiutarti se un giorno avrai bisogno che io 'trovi' qualcosa nelle tasche di qualcuno per te. I goblin sono maestri della furtività!"; }		case LanguageType::JAPANESE:				{ return "もし君が誰かのポケットから何かを'見つける'のに僕を必要とするなら、手伝えるよ。ゴブリンはステルスの達人だからね！"; }
			case LanguageType::KOREAN:					{ return "네가 누군가의 주머니에서 뭔가를 '찾아야' 할 때 내가 도와줄 수도 있어. 고블린은 은신의 달인이거든!"; }		case LanguageType::NORWEGIAN:				{ return "Jeg kan også hjelpe deg hvis du noen gang trenger at jeg 'finner' noe i noens lommer for deg. Gobliner er mestere i sniking!"; }
			case LanguageType::POLISH:					{ return "Mogę też ci pomóc, jeśli kiedyś będziesz potrzebować, żebym 'znalazł' coś w czyichś kieszeniach dla ciebie. Gobliny są mistrzami skradania!"; }		case LanguageType::PORTUGUESE:				{ return "Também te posso ajudar se algum dia precisares que eu 'encontre' algo nos bolsos de alguém por ti. Os goblins são mestres da furtividade!"; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Também posso te ajudar se algum dia você precisar que eu 'encontre' algo nos bolsos de alguém pra você. Goblins são mestres da furtividade!"; }		case LanguageType::ROMANIAN:				{ return "Te pot ajuta și eu dacă vreodată ai nevoie să 'găsesc' ceva în buzunarele cuiva pentru tine. Goblinii sunt maeștri ai furtivității!"; }
			case LanguageType::RUSSIAN:					{ return "Я тоже могу помочь, если тебе когда-нибудь понадобится, чтобы я 'нашел' что-нибудь в чьих-то карманах для тебя. Гоблины - мастера скрытности!"; }		case LanguageType::SPANISH:					{ return "También puedo ayudarte si alguna vez necesitas que 'encuentre' algo en los bolsillos de alguien para ti. ¡Los goblins son maestros del sigilo!"; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "También puedo ayudarte si alguna vez necesitas que 'encuentre' algo en los bolsillos de alguien para ti. ¡Los goblins son maestros del sigilo!"; }	case LanguageType::SWEDISH:					{ return "Jag kan också hjälpa dig om du någon gång behöver att jag 'hittar' något i någons fickor åt dig. Gobliner är mästare på smygande!"; }
			case LanguageType::THAI:					{ return "ฉันช่วยเธอได้เหมือนกัน ถ้าเมื่อไหร่ที่เธอต้องการให้ฉัน 'หา' อะไรบางอย่างในกระเป๋าของใครสักคนให้เธอ ก็อบลินเป็นเจ้าแห่งการลอบเร้น!"; }		case LanguageType::TURKISH:					{ return "Bir gün biri için birinin ceplerinde bir şey 'bulmamı' istersen sana yardım edebilirim. Goblinler gizliliğin ustalarıdır!"; }
			case LanguageType::UKRAINIAN:				{ return "Я теж можу допомогти тобі, якщо колись тобі знадобиться, щоб я 'знайшов' щось у чиїхось кишенях для тебе. Гобліни - майстри непомітності!"; }		case LanguageType::VIETNAMESE:				{ return "Tôi cũng có thể giúp bạn nếu có lúc bạn cần tôi 'tìm' thứ gì đó trong túi của ai đó cho bạn. Goblin là bậc thầy lén lút!"; }
			default: case LanguageType::ENGLISH:		{ return "I can also help you out if you ever need me to 'find' something in someone's pockets for you. Goblins are masters of stealth!"; }
		}
	}
