	std::string Platformer_Quests_EndianForest_SaveTown_Sarude_C_Infiltrate::getStringByLanguage(LanguageType languageType)
	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return ".لن نفوز في معركة عادلة. وبينما نعزلهم ، ابحث عن طريقة للتسلل إلى صفوفهم"; }		case LanguageType::BULGARIAN:				{ return "Никога няма да спечелим в честна борба. Докато ги задържаме, намерете начин да проникнете в техните редици."; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "我们永远不会在公平竞争中获胜。当我们阻止他们时，找到一种方法来渗透他们的队伍。"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "我們永遠不會在公平競爭中獲勝。當我們阻止他們時，找到一種方法來滲透他們的隊伍。"; }
			case LanguageType::CZECH:					{ return "Ve spravedlivém boji nikdy nevyhrajeme. Zatímco je zadržujeme, najděte způsob, jak infiltrovat jejich řady."; }		case LanguageType::DANISH:					{ return "Vi vinder aldrig i en retfærdig kamp. Mens vi holder dem væk, finder vi en måde at infiltrere deres rækker på."; }
			case LanguageType::DUTCH:					{ return "We zullen nooit winnen in een eerlijk gevecht. Terwijl we ze afhouden, zoeken we een manier om hun gelederen te infiltreren."; }		case LanguageType::FINNISH:					{ return "Emme koskaan voita reilussa taistelussa. Kun pidämme heitä pois, löydämme tapa tunkeutua heidän riveihinsä."; }
			case LanguageType::FRENCH:					{ return "Nous ne gagnerons jamais dans un combat loyal. Pendant que nous les retenons, trouvez un moyen d'infiltrer leurs rangs."; }		case LanguageType::GERMAN:					{ return "Wir werden niemals in einem fairen Kampf gewinnen. Während wir sie zurückhalten, finden Sie einen Weg, ihre Reihen zu infiltrieren."; }
			case LanguageType::GREEK:					{ return "Ποτέ δεν θα κερδίσουμε σε μια δίκαιη μάχη. Ενώ τους κρατάμε μακριά, βρούμε έναν τρόπο να διεισδύσουν στις τάξεις τους."; }		case LanguageType::HUNGARIAN:				{ return "Soha nem nyerünk tisztességes harcban. Amíg visszatartjuk őket, keresse meg a módját, hogy beszivárogjon a soraikba."; }
			case LanguageType::ITALIAN:					{ return "Non vinceremo mai in una lotta leale. Mentre li tratteniamo, trova un modo per infiltrarsi nei loro ranghi."; }		case LanguageType::JAPANESE:				{ return "公正な戦いで勝つことは決してありません。私たちが彼らを抑えている間、彼らのランクに潜入する方法を見つけてくだ さい。"; }
			case LanguageType::KOREAN:					{ return "우리는 공정한 싸움에서 결코 이길 수 없습니다. 우리가 그들을 막고있는 동안, 그들의 계급에 침투하는 방법을 찾으십시오."; }		case LanguageType::NORWEGIAN:				{ return "Vi vil aldri vinne i en rettferdig kamp. Mens vi holder dem av, finn en måte å infiltrere deres rekker."; }
			case LanguageType::POLISH:					{ return "Nigdy nie wygramy w uczciwej walce. Podczas gdy my je powstrzymujemy, znajdź sposób na infiltrację ich szeregów."; }		case LanguageType::PORTUGUESE:				{ return "Nós nunca venceremos em uma luta justa. Enquanto os afastamos, encontre uma maneira de se infiltrar em suas fileiras."; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Nós nunca venceremos em uma luta justa. Enquanto os afastamos, encontre uma maneira de se infiltrar em suas fileiras."; }		case LanguageType::ROMANIAN:				{ return "Nu vom câștiga niciodată într-o luptă corectă. În timp ce îi ținem departe, găsiți o modalitate de a se infiltra în rândurile lor."; }
			case LanguageType::RUSSIAN:					{ return "Мы никогда не победим в честной борьбе. Пока мы их сдерживаем, найдите способ проникнуть в их ряды."; }		case LanguageType::SPANISH:					{ return "Nunca ganaremos en una pelea justa. Mientras los detenemos, encuentre la manera de infiltrarse en sus filas."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "Nunca ganaremos en una pelea justa. Mientras los detenemos, encuentre la manera de infiltrarse en sus filas."; }	case LanguageType::SWEDISH:					{ return "Vi kommer aldrig att vinna i en rättvis kamp. Medan vi håller dem borta, hitta ett sätt att infiltrera deras rang."; }
			case LanguageType::THAI:					{ return "เราจะไม่มีวันชนะในการต่อสู้ที่ยุติธรรม ในขณะที่เราหยุดพวกเขาค้นหาวิธีที่จะแทรกซึมตำแหน่งของพวกเขา"; }		case LanguageType::TURKISH:					{ return "Adil bir dövüşte asla kazanmayız. Onları uzak tutarken, saflarına sızmanın bir yolunu bulun."; }
			case LanguageType::UKRAINIAN:				{ return "Ми ніколи не переможемо у чесній боротьбі. Поки ми їх стримуємо, знайдемо спосіб проникнути в їх ряди."; }		case LanguageType::VIETNAMESE:				{ return "Chúng tôi sẽ không bao giờ chiến thắng trong một cuộc chiến công bằng. Trong khi chúng tôi giữ họ lại, tìm cách thâm nhập vào hàng ngũ của họ."; }
			default: case LanguageType::ENGLISH:		{ return "We will never win in a fair fight. While we hold them off, find a way to infiltrate their ranks."; }
		}
	}
