	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return ".زحفت الوحوش من نافورة المياه لدينا. من بينها ميدوسا ، التي حولت سكان المدينة إلى حجر"; }		case LanguageType::BULGARIAN:				{ return "Чудовища изпълзяха от чешмата ни. Сред тях била и една Медуза, която превърнала жителите на града в камък."; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "怪物从我们的喷泉中爬出来。其中包括美杜莎，它将镇民变成了石头。"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "怪物從我們的噴泉中爬出來。其中包括美杜莎，它將鎮民變成了石頭。"; }
			case LanguageType::CZECH:					{ return "Z naší vodní fontány vylezly příšery. Mezi nimi byla i Medúza, která proměnila měšťany v kámen."; }		case LanguageType::DANISH:					{ return "Monstre kravlede ud af vores vandfontæne. Blandt dem var en Medusa, som forvandlede byens borgere til sten."; }
			case LanguageType::DUTCH:					{ return "Monsters kropen uit onze waterfontein. Onder hen was een Medusa, die de stedelingen in steen veranderde."; }		case LanguageType::FINNISH:					{ return "Hirviöt ryömivät ulos suihkulähteestämme. Heidän joukossaan oli Medusa, joka muutti kaupunkilaiset kiveksi."; }
			case LanguageType::FRENCH:					{ return "Des monstres ont rampé hors de notre fontaine d’eau. Parmi eux se trouvait une Méduse, qui transforma les citadins en pierre."; }		case LanguageType::GERMAN:					{ return "Monster krochen aus unserem Wasserbrunnen. Unter ihnen befand sich eine Medusa, die die Stadtbewohner in Stein verwandelte."; }
			case LanguageType::GREEK:					{ return "Τέρατα σέρνονται έξω από το σιντριβάνι μας. Ανάμεσά τους ήταν και η Μέδουσα, που μεταμόρφωνε τους κατοίκους της πόλης σε πέτρα."; }		case LanguageType::HUNGARIAN:				{ return "Szörnyek kúsztak ki a szökőkútunkból. Közülük egy Medusa volt, amely a városlakókat kővé alakította."; }
			case LanguageType::ITALIAN:					{ return "I mostri strisciavano fuori dalla nostra fontana. Tra questi c'era una Medusa, che trasformava i cittadini in pietra."; }		case LanguageType::JAPANESE:				{ return "モンスターが私たちの噴水から這い出しました。その中には、町民を石に変えたメデューサがありました。"; }
			case LanguageType::KOREAN:					{ return "괴물들이 우리 분수대에서 기어 나왔다. 그 중에는 마을 사람들을 돌로 변모시킨 메두사가 있었습니다."; }		case LanguageType::NORWEGIAN:				{ return "Monstre krøp ut av vannfontenen vår. Blant dem var en Medusa, som forvandlet bymennene til stein."; }
			case LanguageType::POLISH:					{ return "Potwory wypełzły z naszej fontanny. Wśród nich była Meduza, która przekształciła mieszczan w kamień."; }		case LanguageType::PORTUGUESE:				{ return "Monstros rastejaram para fora de nossa fonte de água. Entre eles estava uma Medusa, que transformou os habitantes da cidade em pedra."; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Monstros rastejavam para fora de nossa fonte de água. Entre eles estava uma Medusa, que transformou os habitantes da cidade em pedra."; }		case LanguageType::ROMANIAN:				{ return "Monștrii s-au târât din fântâna noastră cu apă. Printre ei s-a numărat și o Meduză, care i-a transformat pe orășeni în piatră."; }
			case LanguageType::RUSSIAN:					{ return "Монстры выползали из нашего фонтана. Среди них была и Медуза, которая превращала горожан в камень."; }		case LanguageType::SPANISH:					{ return "Los monstruos salieron de nuestra fuente de agua. Entre ellos había una Medusa, que transformó a la gente del pueblo en piedra."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "Los monstruos salieron de nuestra fuente de agua. Entre ellos había una Medusa, que transformó a la gente del pueblo en piedra."; }	case LanguageType::SWEDISH:					{ return "Monster kröp ut ur vår vattenfontän. Bland dem var en Medusa, som förvandlade stadsborna till sten."; }
			case LanguageType::THAI:					{ return "สัตว์ประหลาดคลานออกมาจากน้ําพุของเรา ในหมู่พวกเขาคือเมดูซ่าซึ่งเปลี่ยนชาวเมืองให้เป็นหิน"; }		case LanguageType::TURKISH:					{ return "Canavarlar su çeşmemizden sürünerek çıktı. Bunların arasında kasaba halkını taşa dönüştüren bir Medusa da vardı."; }
			case LanguageType::UKRAINIAN:				{ return "Монстри виповзли з нашого водного фонтану. Серед них була і Медуза, яка перетворювала городян в камінь."; }		case LanguageType::VIETNAMESE:				{ return "Quái vật bò ra khỏi đài phun nước của chúng tôi. Trong số đó có một Medusa, biến người dân thị trấn thành đá."; }
			default: case LanguageType::ENGLISH:		{ return "Monsters crawled out of our water fountain. Among them was a Medusa, which transformed the townspeople into stone."; }
		}
	}
