	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return ".الطريقة الوحيدة لعلاج اللعنة هي أن تحدق في '%s1'. أنا متأكد أن الـ(ميدوسا) يحتفظون بواحدة في مكان قريب"; }		case LanguageType::BULGARIAN:				{ return "Единственият начин да се излекува проклятието е да се вгледаме в '%s1'. Сигурна съм, че Медуза държи един наблизо."; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "治愈诅咒的唯一方法是凝视一个'%s1'。我敢肯定美杜莎在附近留着一个。"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "治癒詛咒的唯一方法是凝視一個'%s1'。我敢肯定美杜莎在附近留著一個。"; }
			case LanguageType::CZECH:					{ return "Jediný způsob, jak vyléčit kletbu, je dívat se do '%s1'. Jsem si jistý, že Medúza ho má poblíž."; }		case LanguageType::DANISH:					{ return "Den eneste måde at helbrede forbandelsen er at stirre ind i en '%s1'. Jeg er sikker på, at Medusa holder en i nærheden."; }
			case LanguageType::DUTCH:					{ return "De enige manier om de vloek te genezen is om te staren in een '%s1'. Ik weet zeker dat de Medusa er een in de buurt houdt."; }		case LanguageType::FINNISH:					{ return "Ainoa tapa parantaa kirous on katsoa '%s1'. Olen varma, että Medusa pitää yhden lähellä."; }
			case LanguageType::FRENCH:					{ return "La seule façon de guérir la malédiction est de regarder dans un « %s1 ». Je suis sûr que la Méduse en garde un à proximité."; }		case LanguageType::GERMAN:					{ return "Der einzige Weg, den Fluch zu heilen, ist, in ein '%s1' zu blicken. Ich bin sicher, dass die Medusa einen in der Nähe hält."; }
			case LanguageType::GREEK:					{ return "Ο μόνος τρόπος για να θεραπεύσει την κατάρα είναι να ατενίσει σε ένα '%s1'. Είμαι σίγουρος ότι η Μέδουσα κρατάει ένα εδώ κοντά."; }		case LanguageType::HUNGARIAN:				{ return "Az átok gyógyításának egyetlen módja, ha egy '%s1'-be nézel. Biztos vagyok benne, hogy Medúza tart egyet a közelben."; }
			case LanguageType::ITALIAN:					{ return "L'unico modo per curare la maledizione è guardare in un '%s1'. Sono sicuro che la Medusa ne tiene uno nelle vicinanze."; }		case LanguageType::JAPANESE:				{ return "呪いを解く唯一の方法は、『%s1』を見つめることです。メドゥーサが近くに1つ持っているはずです。"; }
			case LanguageType::KOREAN:					{ return "저주를 풀 수 있는 유일한 방법은 '%s1'를 응시하는 것이다. 메두사가 근처에 하나를 가지고 있을 거야."; }		case LanguageType::NORWEGIAN:				{ return "Den eneste måten å kurere forbannelsen er å stirre inn i en '%s1'. Jeg er sikker på at Medusa holder en i nærheten."; }
			case LanguageType::POLISH:					{ return "Jedynym sposobem na wyleczenie klątwy jest spojrzenie w '%s1'. Jestem pewien, że Meduza trzyma jeden w pobliżu."; }		case LanguageType::PORTUGUESE:				{ return "A única maneira de curar a maldição é olhar para um '%s1'. Tenho a certeza que a Medusa mantém uma por perto."; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "A única maneira de curar a maldição é olhar para um '%s1'. Tenho certeza que a Medusa mantém uma por perto."; }		case LanguageType::ROMANIAN:				{ return "Singura modalitate de a vindeca blestemul este de a privi într-un '%s1'. Sunt sigur că Medusa ține una în apropiere."; }
			case LanguageType::RUSSIAN:					{ return "Единственный способ снять проклятие — смотреть в '%s1'. Я уверен, что Медуза держит один поблизости."; }		case LanguageType::SPANISH:					{ return "La única manera de curar la maldición es mirar a un '%s1'. Estoy seguro de que la Medusa mantiene una cerca."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "La única manera de curar la maldición es mirar a un '%s1'. Estoy seguro de que la Medusa mantiene una cerca."; }	case LanguageType::SWEDISH:					{ return "Det enda sättet att bota förbannelsen är att blicka in i en '%s1'. Jag är säker på att Medusa har en i närheten."; }
			case LanguageType::THAI:					{ return "วิธีเดียวที่จะรักษาคําสาปคือการจ้องมองเข้าไปใน '%s1' ฉันแน่ใจว่าเมดูซ่าเก็บหนึ่งใกล้เคียง"; }		case LanguageType::TURKISH:					{ return "Laneti iyileştirmenin tek yolu bir '%s1'e bakmak. Medusa'nın yakınlarda bir tane tuttuğuna eminim."; }
			case LanguageType::UKRAINIAN:				{ return "Єдиний спосіб зняти прокляття — дивитися в '%s1'. Я впевнений, що Медуза тримає один поблизу."; }		case LanguageType::VIETNAMESE:				{ return "Cách duy chỉ để chữa trị lời nguyền là để chiêm ngưỡng một '%s1'. Tôi chắc rằng Medusa giữ một gần đó."; }
			default: case LanguageType::ENGLISH:		{ return "The only way to cure the curse is to gaze into a '%s1'. I'm sure the Medusa keeps one nearby."; }
		}
	}
