	std::string Platformer_Quests_WarpGates_WarpGateIntro::getStringByLanguage(LanguageType languageType)
	{
		switch (languageType)
		{
			case LanguageType::ARABIC:					{ return "هذا هو ضريح الاعوجاج. إذا اكتشفت مواقع الاعوجاج الأخرى في رحلتك ، فقم بتنشيطها! سيسمح لك القيام بذلك بالالتواء بسرعة بين الأراضي البعيدة."; }		case LanguageType::BULGARIAN:				{ return "Това е светлинното светилище. Ако откриете други светлинни места по време на пътуването си, активирайте ги! Това ще ви позволи бързо да се изкривите между далечни земи."; }
			case LanguageType::CHINESE_SIMPLIFIED:		{ return "这是传送神龛。如果您在旅途中发现其他传送点，请激活它们！这样您就能在遥远的土地之间快速传送。"; }		case LanguageType::CHINESE_TRADITIONAL:		{ return "這是傳送神龕。如果您在旅途中發現其他傳送點，請啟動它們！這樣您就能在遙遠的土地之間快速傳送。"; }
			case LanguageType::CZECH:					{ return "Toto je warpová svatyně. Pokud na své cestě objevíte další warpová místa, aktivujte je! To vám umožní rychle warpnout mezi vzdálenými zeměmi."; }		case LanguageType::DANISH:					{ return "Dette er warp-helligdommen. Hvis du opdager andre warp-steder på din rejse, skal du aktivere dem! Det giver dig mulighed for hurtigt at warpe mellem fjerne lande."; }
			case LanguageType::DUTCH:					{ return "Dit is het warp-heiligdom. Als je tijdens je reis andere warp-locaties ontdekt, activeer ze dan! Zo kun je snel warpen tussen verre landen."; }		case LanguageType::FINNISH:					{ return "Tämä on warp-pyhäkkö. Jos löydät matkallasi muita warp-paikkoja, aktivoi ne! Näin voit nopeasti warppailla kaukaisten maiden välillä."; }
			case LanguageType::FRENCH:					{ return "C’est le sanctuaire de distorsion. Si vous découvrez d’autres emplacements de distorsion au cours de votre voyage, activez-les! Cela vous permettra de vous déformer rapidement entre des terres lointaines."; }		case LanguageType::GERMAN:					{ return "Dies ist der Warp-Schrein. Wenn du auf deiner Reise weitere Warp-Orte entdeckst, aktiviere sie! Auf diese Weise kannst du schnell zwischen weit entfernten Ländern hin- und herspringen."; }
			case LanguageType::GREEK:					{ return "Αυτό είναι το ιερό στημόνι. Εάν ανακαλύψετε άλλες τοποθεσίες στρέβλωσης στο ταξίδι σας, ενεργοποιήστε τις! Κάτι τέτοιο θα σας επιτρέψει να στρέψετε γρήγορα μεταξύ μακρινών χωρών."; }		case LanguageType::HUNGARIAN:				{ return "Ez a warp szentély. Ha utazásod során más warp helyeket fedezel fel, aktiváld őket! Ezzel gyorsan warpolhatsz a távoli vidékek között."; }
			case LanguageType::ITALIAN:					{ return "Questo è il santuario del warp. Se scopri altri punti warp durante il tuo viaggio, attivali! Così potrai warpare rapidamente tra terre lontane."; }		case LanguageType::JAPANESE:				{ return "これが縦糸神社です。旅の途中で他のワープロケーションを発見したら、それらをアクティブにしてください!そうすることで、遠くの土地間をすばやくワープすることができます。"; }
			case LanguageType::KOREAN:					{ return "이곳은 워프 신사입니다. 여행 중에 다른 워프 위치를 발견하면 활성화하세요! 그렇게 하면 멀리 떨어진 땅 사이를  빠르게 워프할 수 있습니다."; }		case LanguageType::NORWEGIAN:				{ return "Dette er warp-helligdommen. Hvis du oppdager andre warp-steder på reisen, aktiverer du dem! Da kan du raskt warpe mellom fjerne land."; }
			case LanguageType::POLISH:					{ return "To jest sanktuarium osnowy. Jeśli odkryjesz inne miejsca warp podczas swojej podróży, aktywuj je! Pozwoli ci to szybko przeskakiwać między odległymi krainami."; }		case LanguageType::PORTUGUESE:				{ return "Este é o santuário de warp. Se descobrires outros pontos de warp na tua jornada, ativa-os! Isso permitir-te-á viajar rapidamente entre terras distantes."; }
			case LanguageType::PORTUGUESE_BRAZIL:		{ return "Este é o santuário de warp. Se você descobrir outros pontos de warp em sua jornada, ative-os! Isso permitirá que você viaje rapidamente entre terras distantes."; }		case LanguageType::ROMANIAN:				{ return "Acesta este altarul de warp. Dacă descoperiți alte locații de warp în călătoria dvs., activați-le! Acest lucru vă va permite să vă deplasați rapid între tărâmuri îndepărtate."; }
			case LanguageType::RUSSIAN:					{ return "Это варп-святилище. Если вы обнаружите другие варп-локации в своем путешествии, активируйте их! Это позволит вам быстро перемещаться между далекими землями."; }		case LanguageType::SPANISH:					{ return "Este es el santuario warp. Si descubres otras ubicaciones warp en tu viaje, ¡actívalas! Hacerlo te permitirá deformarte rápidamente entre tierras lejanas."; }
			case LanguageType::SPANISH_LATIN_AMERICAN:	{ return "Este es el santuario warp. Si descubres otras ubicaciones warp en tu viaje, ¡actívalas! Hacerlo te permitirá deformarte rápidamente entre tierras lejanas."; }	case LanguageType::SWEDISH:					{ return "Detta är varphelgedomen. Om du upptäcker andra varpplatser på din resa, aktivera dem! Om du gör det kan du snabbt varpa mellan fjärran länder."; }
			case LanguageType::THAI:					{ return "นี่คือศาลเจ้าวิปริต หากคุณค้นพบสถานที่วิปริตอื่น ๆ ในการเดินทางของคุณเปิดใช้งานพวกเขา! การทําเช่นนี้จะช่วยให้คุณบิดเบี้ยวระหว่างดินแดนที่ห่างไกลได้อย่างรวดเร็ว"; }		case LanguageType::TURKISH:					{ return "Bu warp tapınağı. Yolculuğunuzda başka warp noktaları keşfederseniz, onları etkinleştirin! Böylece uzak diyarlar arasında hızlıca warp yapabilirsiniz."; }
			case LanguageType::UKRAINIAN:				{ return "Це святиня варпу. Якщо ви виявите інші точки варпу під час своєї подорожі, активуйте їх! Це дозволить вам швидко переміщатися між далекими землями."; }		case LanguageType::VIETNAMESE:				{ return "Đây là đền warp. Nếu bạn khám phá các điểm warp khác trong hành trình của mình, hãy kích hoạt chúng! Làm vậy sẽ giúp bạn nhanh chóng warp giữa các vùng đất xa xôi."; }
			default: case LanguageType::ENGLISH:		{ return "This is the warp shrine. If you discover other warp locations on your journey, activate them! Doing so will allow you to quickly warp between far away lands."; }
		}
	}
